local bundledModules = {}
local loadedModules = {}
local function require(modulePath)
	local cached = loadedModules[modulePath]
	if cached ~= nil then
		return table.unpack(cached, 1, cached.n)
	end
	local loader = bundledModules[modulePath]
	assert(loader, "YSL Method bundle is missing module: " .. tostring(modulePath))
	local results = table.pack(loader())
	loadedModules[modulePath] = results
	return table.unpack(results, 1, results.n)
end

