	["@src/utility/librarys/components/dropdown"] = function()




return function(Library, context)
	local InputService = context.InputService
	local Mouse = context.Mouse
	local ScreenGui = context.ScreenGui or Library.ScreenGui
	local TweenService = game:GetService('TweenService')

	local Component = {}

	local function getPlayersString()
		local PlayerList = game:GetService('Players'):GetPlayers()

		for i = 1, #PlayerList do
			PlayerList[i] = PlayerList[i].Name
		end

		table.sort(PlayerList, function(str1, str2) return str1 < str2 end)

		return PlayerList
	end

	local function getTeamsString()
		local TeamList = game:GetService('Teams'):GetTeams()

		for i = 1, #TeamList do
			TeamList[i] = TeamList[i].Name
		end

		table.sort(TeamList, function(str1, str2) return str1 < str2 end)

		return TeamList
	end

	function Component.AddDropdown(self, Idx, Info)
		Info.Searchable = if typeof(Info.Searchable) == 'boolean' then Info.Searchable else false
		if Info.SpecialType == 'Player' then
			Info.Values = getPlayersString()
			Info.AllowNull = true
		elseif Info.SpecialType == 'Team' then
			Info.Values = getTeamsString()
			Info.AllowNull = true
		end

		assert(Info.Values, 'AddDropdown: Missing dropdown value list.')
		assert(Info.AllowNull or Info.Default, 'AddDropdown: Missing default value. Pass `AllowNull` as true if this was intentional.')

		if not Info.Text then
			Info.Compact = true
		end
		
		if self.Objects then
			table.insert(self.Objects, {
				internal_name = Idx, settings = Info
			})
		end;

		local Dropdown: {[string]: any} = {
			Values = Info.Values;
			Value = Info.Multi and {};
			Multi = Info.Multi;
			Type = 'Dropdown';
			Flag = Idx;
			SpecialType = Info.SpecialType;
			Callback = Info.Callback or function(_) end;
			Name = Info.Text
		}

		local Groupbox = self
		local Container = Groupbox.Container
		local RelativeOffset = 0

		if not Info.Compact then
			Library:CreateLabel({
				Size = UDim2.new(1, 0, 0, 10);
				TextSize = 14;
				Text = Info.Text;
				TextXAlignment = Enum.TextXAlignment.Left;
				TextYAlignment = Enum.TextYAlignment.Bottom;
				ZIndex = 5;
				Parent = Container;
			})

			Groupbox:AddBlank(3)
		end

		for _, Element in next, Container:GetChildren() do
			if not Element:IsA('UIListLayout') then
				RelativeOffset = RelativeOffset + Element.Size.Y.Offset
			end
		end

		
		
		
		
		
		local DropdownOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, -4, 0, 20);
			ZIndex = 5;
			Parent = Container;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 2); Parent = DropdownOuter })

		Library:AddToRegistry(DropdownOuter, {
			BorderColor3 = 'Black';
		})

		local DropdownInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 6;
			Parent = DropdownOuter;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 1); Parent = DropdownInner })

		if type(Info.Text) == 'string' and Info.Text ~= '' then
			Library:RegisterSearchEntry(Groupbox, {
				Kind = 'Dropdown';
				Text = Info.Text;
				Tab = Groupbox.Tab or Groupbox;
				Target = DropdownOuter;
				Focus = function()
					Library:FocusSearchTarget(DropdownOuter)
				end;
			})
		end

		Library:AddToRegistry(DropdownInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local function SetChromeHidden(Hidden)
			DropdownOuter.BackgroundTransparency = Hidden and 1 or 0
			DropdownOuter.BorderSizePixel = Hidden and 0 or 1
			DropdownInner.BackgroundTransparency = Hidden and 1 or 0
			DropdownInner.BorderSizePixel = Hidden and 0 or 1
		end

		local MAX_DROPDOWN_ITEMS = 8
		local BUTTON_HEIGHT = 20

		local Overlay = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			BorderMode = Enum.BorderMode.Inset;
			Visible = false;
			ZIndex = 20;
			Parent = ScreenGui;
		})

		Library:AddUIScale(Overlay)

		Library:AddToRegistry(Overlay, {
			BorderColor3 = 'Black';
		})

		local OverlayInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 21;
			Parent = Overlay;
		})

		Library:AddToRegistry(OverlayInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local ListOpened = false
		local ListContentHeight = MAX_DROPDOWN_ITEMS * 20

		local function RecalculateOverlay()
			local Height = BUTTON_HEIGHT + (ListOpened and ListContentHeight or 0)
			Overlay.Position = UDim2.fromOffset(DropdownOuter.AbsolutePosition.X, DropdownOuter.AbsolutePosition.Y)
			Overlay.Size = UDim2.fromOffset(DropdownOuter.AbsoluteSize.X / Library:GetUIScale(), ListOpened and Height - 3 or Height)
		end

		RecalculateOverlay()

		
		
		
		
		
		local DropdownInnerSearch
		if Info.Searchable then
			DropdownInnerSearch = Library:Create('TextBox', {
				BackgroundTransparency = 1;
				Visible = false;
				Position = UDim2.new(0, 5, 0, 0);
				Size = UDim2.new(0.9, -5, 0, BUTTON_HEIGHT);
				FontFace = Library.Font;
				PlaceholderColor3 = Color3.fromRGB(190, 190, 190);
				PlaceholderText = 'Search...';
				Text = '';
				TextColor3 = Library.FontColor;
				TextSize = 14;
				TextStrokeTransparency = 0;
				TextXAlignment = Enum.TextXAlignment.Left;
				ClearTextOnFocus = false;
				ZIndex = 23;
				Parent = DropdownInner;
			})

			Library:ApplyTextStroke(DropdownInnerSearch)

			Library:AddToRegistry(DropdownInnerSearch, {
				TextColor3 = 'FontColor';
			})
		end

		local DropdownArrow = Library:Create('ImageLabel', {
			AnchorPoint = Vector2.new(0, 0.5);
			BackgroundTransparency = 1;
			Position = UDim2.new(1, -16, 0, BUTTON_HEIGHT / 2);
			Size = UDim2.new(0, 12, 0, 12);
			Image = 'http://www.roblox.com/asset/?id=6282522798';
			ZIndex = 7;
			Parent = DropdownInner;
		})

		local ItemList = Library:CreateLabel({
			Position = UDim2.new(0, 1, 0, 2);
			Size = UDim2.new(1, -1, 0, BUTTON_HEIGHT - 2);
			TextSize = 14;
			Text = 'Select...';
			TextXAlignment = Enum.TextXAlignment.Left;
			TextYAlignment = Enum.TextYAlignment.Top;
			TextWrapped = true;
			ZIndex = 8;
			Parent = DropdownInner;
		})

		if type(Info.Tooltip) == 'string' then
			Library:AddToolTip(Info.Tooltip, DropdownOuter)
		end

		local ListInner = Library:Create('Frame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 0, 0, BUTTON_HEIGHT);
			Size = UDim2.new(1, 0, 1, -BUTTON_HEIGHT);
			Visible = false;
			ZIndex = 21;
			Parent = OverlayInner;
		})

		DropdownOuter:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
			RecalculateOverlay()
		end)

		DropdownOuter:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
			RecalculateOverlay()
		end)

		Library:OnHighlight(DropdownOuter, DropdownOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		Library:OnHighlight(DropdownOuter, Overlay,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		Library:OnHighlight(ListInner, Overlay,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		local Scrolling = Library:Create('ScrollingFrame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			CanvasSize = UDim2.new(0, 0, 0, 0);
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 21;
			Parent = ListInner;

			TopImage = 'rbxasset://textures/ui/Scroll/scroll-middle.png',
			BottomImage = 'rbxasset://textures/ui/Scroll/scroll-middle.png',

			ScrollBarThickness = 3,
			ScrollBarImageColor3 = Library.AccentColor,
		})

		Library:AddToRegistry(Scrolling, {
			ScrollBarImageColor3 = 'AccentColor'
		})

		Library:Create('UIListLayout', {
			Padding = UDim.new(0, 0);
			FillDirection = Enum.FillDirection.Vertical;
			SortOrder = Enum.SortOrder.LayoutOrder;
			Parent = Scrolling;
		})

		function Dropdown:Display()
			local Values = Dropdown.Values
			local Str = ''

			if Info.Multi then
				for _, Value in next, Values do
					if Dropdown.Value[Value] then
						Str = Str .. Value .. ', '
					end
				end

				Str = Str:sub(1, #Str - 2)
			else
				Str = Dropdown.Value or ''
			end

			ItemList.Text = (Str == '' and 'Select...' or Str)
			Library:UpdateDependencyBoxes()
		end

		function Dropdown:GetActiveValues()
			if Info.Multi then
				local T = {}
				for Value, _ in next, Dropdown.Value do
					table.insert(T, Value)
				end
				return T
			end

			return Dropdown.Value and 1 or 0
		end

		local built = false;
		function Dropdown:BuildDropdownList()
			local Values = Dropdown.Values
			local Buttons = {}

			for _, Element in next, Scrolling:GetChildren() do
				if not Element:IsA('UIListLayout') then
					Element:Destroy()
				end
			end

			local Count = 0
			local searchTerm = DropdownInnerSearch and string.lower(DropdownInnerSearch.Text)

			for _, Value in next, Values do
				if Info.Searchable and #searchTerm > 0 then
					local StringValue = typeof(Value) == 'Instance' and Value.Name or Value
					if not string.lower(StringValue):find(searchTerm, 1, true) then
						continue
					end
				end

				local ButtonState: {[string]: any} = {}
				Count = Count + 1

				local Button = Library:Create('Frame', {
					BackgroundColor3 = Library.OutlineColor;
					BackgroundTransparency = 1;
					BorderSizePixel = 0;
					Size = UDim2.new(1, -1, 0, 20);
					ZIndex = 23;
					Active = true;
					Parent = Scrolling;
				})

				Library:AddToRegistry(Button, {
					BackgroundColor3 = 'OutlineColor';
				})

				local ButtonLabel = Library:CreateLabel({
					Active = false;
					Size = UDim2.new(1, -6, 1, 0);
					Position = UDim2.new(0, 6, 0, 0);
					TextSize = 14;
					Text = Value;
					TextXAlignment = Enum.TextXAlignment.Left;
					ZIndex = 24;
					Parent = Button;
				})

				Library:OnHighlight(Button, Button,
					{ BackgroundTransparency = 0 },
					{ BackgroundTransparency = 1 }
				)

				local Selected = Info.Multi and Dropdown.Value[Value] or (Dropdown.Value == Value)

				function ButtonState:UpdateButton()
					if Info.Multi then
						Selected = Dropdown.Value[Value]
					else
						Selected = Dropdown.Value == Value
					end

					ButtonLabel.TextColor3 = Selected and Library.AccentColor or Library.FontColor
					Library.RegistryMap[ButtonLabel].Properties.TextColor3 = Selected and 'AccentColor' or 'FontColor'
				end

				ButtonLabel.InputBegan:Connect(function(Input)
					if Input.UserInputType ~= Enum.UserInputType.MouseButton1 then
						return
					end

					local Try = not Selected

					if Dropdown:GetActiveValues() == 1 and (not Try) and (not Info.AllowNull) then
						return
					end

					if Info.Multi then
						Selected = Try

						if Selected then
							Dropdown.Value[Value] = true
						else
							Dropdown.Value[Value] = nil
						end
					else
						Selected = Try

						if Selected then
							Dropdown.Value = Value
						else
							Dropdown.Value = nil
						end

						for _, OtherButton in next, Buttons do
							OtherButton:UpdateButton()
						end
					end

					ButtonState:UpdateButton()
					Dropdown:Display()

					Library:SafeCallback(Dropdown.Callback, Dropdown.Value)
					Library:SafeCallback(Dropdown.Changed, Dropdown.Value)

					Library:AttemptSave()
				end)

				ButtonState:UpdateButton()
				Buttons[Button] = ButtonState
			end

			Scrolling.CanvasSize = UDim2.fromOffset(0, (Count * 20) + 1)
			ListContentHeight = math.clamp(Count * 20, 0, MAX_DROPDOWN_ITEMS * 20) + 8
			RecalculateOverlay()
			Dropdown:Display()
		end

		function Dropdown:SetValues(NewValues)
			if NewValues then
				Dropdown.Values = NewValues
			end

			
			Dropdown:BuildDropdownList()
		end

		function Dropdown:OpenDropdown()
			if Info.Searchable then
				ItemList.Visible = false
				DropdownInnerSearch.Text = ''
				DropdownInnerSearch.Visible = true
				DropdownInnerSearch.Parent = OverlayInner
			end

			DropdownArrow.Parent = OverlayInner
			ItemList.Parent = OverlayInner
			SetChromeHidden(true)

			ListOpened = true
			ListInner.Visible = true
			Overlay.Visible = true
			RecalculateOverlay()
			Library.OpenedFrames[ListInner] = true
			DropdownArrow.Rotation = 180
			ItemList.ZIndex = 22;
			DropdownArrow.ZIndex = 22;

			if not built then
				Dropdown:BuildDropdownList()
				built = true;
			end
		end

		function Dropdown:CloseDropdown()
			if not DropdownOuter.Parent or not Overlay.Parent or not DropdownInner.Parent then
				ListOpened = false
				Library.OpenedFrames[ListInner] = nil
				return
			end

			if Info.Searchable then
				DropdownInnerSearch.Text = ''
				DropdownInnerSearch.Visible = false
				ItemList.Visible = true
				if DropdownInnerSearch.Parent then
					DropdownInnerSearch.Parent = DropdownInner
				end
			end
			ItemList.ZIndex = 7;
			DropdownArrow.ZIndex = 7;
			DropdownArrow.Parent = DropdownInner
			ItemList.Parent = DropdownInner
			SetChromeHidden(false)

			ListOpened = false
			ListInner.Visible = false
			Overlay.Visible = false
			RecalculateOverlay()
			Library.OpenedFrames[ListInner] = nil
			DropdownArrow.Rotation = 0
		end

		function Dropdown:OnChanged(Func)
			Dropdown.Changed = Func
			Func(Dropdown.Value)
		end

		function Dropdown:SetValue(Val, Skip)
			if Dropdown.Multi then
				local nTable = {}

				local is_skip = (
					Idx == 'blocked_timings' or
					Idx == 'automation_usage_mantras' or
					Idx == 'mantra_slidecasting_mantras' or
					Idx == 'action_rolling_mantras' or
					Idx == 'backstab_movestacker_mantras'
				)
				for Value, _ in next, Val do
					if is_skip or table.find(Dropdown.Values, Value) then
						if is_skip and not table.find(Dropdown.Values, Value) then
							table.insert(Dropdown.Values, Value)
						end
						nTable[Value] = true
					end
				end

				Dropdown.Value = nTable
			else
				if not Val then
					Dropdown.Value = nil
				elseif table.find(Dropdown.Values, Val) then
					Dropdown.Value = Val
				end
			end

			Dropdown:Display()
			Library:SafeCallback(Dropdown.Callback, Dropdown.Value)
			Library:SafeCallback(Dropdown.Changed, Dropdown.Value)
		end

		DropdownOuter.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				if ListOpened then
					Dropdown:CloseDropdown()
				else
					Dropdown:OpenDropdown()
				end
			end
		end)

		if Info.Searchable then
			DropdownInnerSearch:GetPropertyChangedSignal('Text'):Connect(function()
				Dropdown:BuildDropdownList()
			end)
		end

		Library:GiveSignal(InputService.InputBegan:Connect(function(Input)
			if not Library.Toggled or not ListOpened then
				return
			end

			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				local AbsPos, AbsSize = Overlay.AbsolutePosition, Overlay.AbsoluteSize
				if Mouse.X < AbsPos.X or Mouse.X > AbsPos.X + AbsSize.X
					or Mouse.Y < AbsPos.Y or Mouse.Y > AbsPos.Y + AbsSize.Y then
					Dropdown:CloseDropdown()
				end
			end
		end))

		local Defaults = {}

		if type(Info.Default) == 'string' then
			local defaultIndex = table.find(Dropdown.Values, Info.Default)
			if defaultIndex then
				table.insert(Defaults, defaultIndex)
			end
		elseif type(Info.Default) == 'table' then
			for _, Value in next, Info.Default do
				local defaultIndex = table.find(Dropdown.Values, Value)
				if defaultIndex then
					table.insert(Defaults, defaultIndex)
				end
			end
		elseif type(Info.Default) == 'number' and Dropdown.Values[Info.Default] ~= nil then
			table.insert(Defaults, Info.Default)
		end

		if next(Defaults) then
			for i = 1, #Defaults do
				local Index = Defaults[i]
				if Info.Multi then
					Dropdown.Value[Dropdown.Values[Index] ] = true
				else
					Dropdown.Value = Dropdown.Values[Index]
				end

				if not Info.Multi then
					break
				end
			end

			
			
		end

		Dropdown:BuildDropdownList()

		Groupbox:AddBlank(Info.BlankSize or 5)
		Groupbox:Resize()

		aztup_options[Idx] = Dropdown
		Library:UpdateDependencyBoxes()
		return Dropdown
	end

	return Component
end
	end,
	["@src/utility/librarys/components/hud"] = function()


return function(Library, context)
	local ScreenGui = context.ScreenGui or Library.ScreenGui
	local Mouse = context.Mouse
	local TweenService = context.TweenService or game:GetService('TweenService')
	local UserInputService = game:GetService('UserInputService')

	local Component = {}

	local NotificationArea = Library:Create('Frame', {
		BackgroundTransparency = 1;
		BorderSizePixel = 0;
		Position = UDim2.new(0, 8, 0, 40);
		Size = UDim2.fromOffset(480, 0);
		ZIndex = 90;
		Parent = ScreenGui;
	})

	Library.NotificationArea = NotificationArea
	Library:AddUIScale(NotificationArea)

	local NotificationLayout = Library:Create('UIListLayout', {
		Padding = UDim.new(0, 4);
		FillDirection = Enum.FillDirection.Vertical;
		SortOrder = Enum.SortOrder.LayoutOrder;
		Parent = NotificationArea;
	})
	NotificationLayout:GetPropertyChangedSignal('AbsoluteContentSize'):Connect(function()
		local scale = math.max(Library:GetUIScale(), 0.01)
		NotificationArea.Size = UDim2.fromOffset(
			NotificationArea.Size.X.Offset,
			NotificationLayout.AbsoluteContentSize.Y / scale
		)
	end)

	local notificationDragConnections = {}
	local function clearNotificationDragConnections()
		for _, connection in ipairs(notificationDragConnections) do
			connection:Disconnect()
		end
		table.clear(notificationDragConnections)
	end

	local function beginNotificationDrag(input, onClick)
		if input.UserInputType ~= Enum.UserInputType.MouseButton1
			and input.UserInputType ~= Enum.UserInputType.Touch then
			return
		end
		clearNotificationDragConnections()
		local touchInput = input.UserInputType == Enum.UserInputType.Touch and input or nil
		local startPointer = Vector2.new(input.Position.X, input.Position.Y)
		local startPosition = NotificationArea.Position
		local scale = math.max(Library:GetUIScale(), 0.01)
		local moved = false
		local function updatePointer(pointer)
			local delta = (pointer - startPointer) / scale
			if not moved and delta.Magnitude < 4 then
				return
			end
			moved = true
			local camera = workspace.CurrentCamera
			local viewport = camera and camera.ViewportSize / scale or Vector2.new(800, 600)
			local maxX = math.max(0, viewport.X - NotificationArea.AbsoluteSize.X / scale)
			local maxY = math.max(0, viewport.Y - NotificationArea.AbsoluteSize.Y / scale)
			local x = math.clamp(startPosition.X.Offset + delta.X, 0, maxX)
			local y = math.clamp(startPosition.Y.Offset + delta.Y, 0, maxY)
			NotificationArea.Position = UDim2.fromOffset(x, y)
		end
		table.insert(notificationDragConnections, UserInputService.InputChanged:Connect(function(changedInput)
			if touchInput then
				if changedInput == touchInput then
					updatePointer(Vector2.new(changedInput.Position.X, changedInput.Position.Y))
				end
			elseif changedInput.UserInputType == Enum.UserInputType.MouseMovement
				and UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
				updatePointer(Vector2.new(changedInput.Position.X, changedInput.Position.Y))
			end
		end))
		table.insert(notificationDragConnections, UserInputService.InputEnded:Connect(function(endedInput)
			local ended = touchInput and endedInput == touchInput
				or (not touchInput and endedInput.UserInputType == Enum.UserInputType.MouseButton1)
			if not ended then
				return
			end
			clearNotificationDragConnections()
			if not moved and onClick then
				onClick()
			end
		end))
	end

	ScreenGui.Destroying:Connect(clearNotificationDragConnections)

	local WatermarkOuter = Library:Create('Frame', {
		Position = UDim2.new(0, 24, 1, -56);
		Size = UDim2.new(0, 180, 0, 36);
		BackgroundColor3 = Library.MainColor;
		BackgroundTransparency = 0.18;
		BorderSizePixel = 0;
		ZIndex = 200;
		Visible = false;
		Parent = ScreenGui;
	})
	Library:AddUIScale(WatermarkOuter)
	Library:Create('UICorner', {
		CornerRadius = UDim.new(0, 10);
		Parent = WatermarkOuter;
	})
	local WatermarkStroke = Library:Create("UIStroke", {
		Color = Library.AccentColor;
		Thickness = 3;
		Transparency = 0.18;
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border;
		Parent = WatermarkOuter;
	})
	Library:AddWindowGradientStroke(WatermarkStroke)
	Library:AddToRegistry(WatermarkStroke, {
		Color = function()
			return Library.WindowOutlineGradientEnabled and Color3.new(1, 1, 1) or Library.AccentColor
		end;
	}, true)

	WatermarkOuter.MouseEnter:Connect(function()
		Library.RequestingMouse = true
	end)

	WatermarkOuter.MouseLeave:Connect(function()
		Library.RequestingMouse = false
	end)

	Library:AddToRegistry(WatermarkOuter, {
		BackgroundColor3 = 'MainColor';
	}, true)

	local WatermarkInner = Library:Create('Frame', {
		Size = UDim2.new(1, -2, 1, -2);
		Position = UDim2.new(0, 1, 0, 1);
		BackgroundColor3 = Library.MainColor;
		BackgroundTransparency = 0.18;
		BorderSizePixel = 0;
		ZIndex = 201;
		Parent = WatermarkOuter;
	})
	Library:Create('UICorner', {
		CornerRadius = UDim.new(0, 9);
		Parent = WatermarkInner;
	})
	Library:AddToRegistry(WatermarkInner, {
		BackgroundColor3 = 'MainColor';
	}, true)
	local WatermarkAccent = Library:Create('Frame', {
		Position = UDim2.fromOffset(8, 8);
		Size = UDim2.new(0, 2, 1, -16);
		BackgroundColor3 = Library.AccentColor;
		BorderSizePixel = 0;
		ZIndex = 202;
		Parent = WatermarkInner;
	})
	Library:AddToRegistry(WatermarkAccent, { BackgroundColor3 = 'AccentColor' }, true)

	local WatermarkText = Library:Create('TextLabel', {
		Position = UDim2.new(0, 19, 0, 3);
		Size = UDim2.new(1, -27, 1, -6);
		BorderSizePixel = 0;
		BackgroundTransparency = 1;
		Text = '';
		TextColor3 = Library.FontColor;
		TextSize = 14;
		TextXAlignment = Enum.TextXAlignment.Left;
		TextStrokeTransparency = 1;
		AutoLocalize = false;
		RichText = true;
		ZIndex = 203;
		Parent = WatermarkInner;
	})
	local sectionSpecs = {
		{ Name = "Brand", Bold = true, Color = Library.FontColor },
		{ Name = "Divider1", Divider = true, Color = Library.AccentColor },
		{ Name = "Player", Color = Library.FontColor },
		{ Name = "Divider2", Divider = true, Color = Library.AccentColor },
		{ Name = "FPS", Color = Library.AccentColor },
		{ Name = "Divider3", Divider = true, Color = Library.AccentColor },
		{ Name = "Ping", Color = Library.AccentColor },
	}
	local watermarkSections = {}
	for _, spec in ipairs(sectionSpecs) do
		local label = Library:Create('TextLabel', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.fromOffset(0, 0);
			Size = UDim2.fromOffset(0, 32);
			FontFace = spec.Bold and lexend.bold or lexend.regular;
			Text = "";
			TextColor3 = spec.Color;
			TextSize = 14;
			TextXAlignment = Enum.TextXAlignment.Left;
			TextYAlignment = Enum.TextYAlignment.Center;
			TextStrokeTransparency = 1;
			AutoLocalize = false;
			Visible = false;
			ZIndex = 203;
			Parent = WatermarkInner;
		})
		Library:AddToRegistry(label, {
			TextColor3 = spec.Divider and "AccentColor"
				or (spec.Bold and "FontColor" or (spec.Name == "Player" and Color3.new(1, 1, 1) or "AccentColor")),
		}, true)
		watermarkSections[spec.Name] = label
	end

	task.spawn(function()
		WatermarkText.FontFace = lexend.regular;
	end);

	Library:ApplyTextStroke(WatermarkText)

	Library:AddToRegistry(WatermarkText, {
		TextColor3 = 'FontColor';
	}, true)

	Library.Watermark = WatermarkOuter
	Library.WatermarkText = WatermarkText
	Library.WatermarkSections = watermarkSections
	Library:MakeDraggable(Library.Watermark)
	Library.HudTransparency = 0.18
	function Library:SetHudTransparency(value)
		Library.HudTransparency = math.clamp(tonumber(value) or 0.18, 0, 0.8)
		local backgroundTransparency = Library.HudTransparency
		WatermarkOuter.BackgroundTransparency = backgroundTransparency
		WatermarkInner.BackgroundTransparency = backgroundTransparency
		WatermarkStroke.Transparency = math.clamp(backgroundTransparency + 0.15, 0, 0.95)
		local keybindFrame = Library.KeybindFrame
		if keybindFrame then
			keybindFrame.BackgroundTransparency = backgroundTransparency
		end
		local keybindInner = Library.KeybindInner
		if keybindInner then
			keybindInner.BackgroundTransparency = backgroundTransparency
		end
		local keybindHeader = Library.KeybindHeader
		if keybindHeader then
			keybindHeader.BackgroundTransparency = backgroundTransparency
		end
		for _, row in ipairs(Library.KeybindContainer and Library.KeybindContainer:GetChildren() or {}) do
			if row:IsA("TextLabel") then
				row.BackgroundTransparency = backgroundTransparency
				local badge = row:FindFirstChild("HotkeyKeyBadge")
				if badge then
					badge.BackgroundTransparency = backgroundTransparency
				end
				local modeBadge = row:FindFirstChild("HotkeyModeBadge")
				if modeBadge then
					modeBadge.BackgroundTransparency = backgroundTransparency
				end
			end
		end
		local targetHUD = Library.TargetHUDFrame
		if targetHUD then
			targetHUD.BackgroundTransparency = backgroundTransparency
		end
		local preview = Library.ESPPreviewFrame
		if preview then
			preview.BackgroundTransparency = backgroundTransparency
		end
		local previewHeader = Library.ESPPreviewHeader
		if previewHeader then
			previewHeader.BackgroundTransparency = backgroundTransparency
		end
		local previewViewport = Library.ESPPreviewViewport
