		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = RangeFill })

		Library:AddToRegistry(RangeFill, {
			BackgroundColor3 = 'AccentColor';
			BorderColor3 = 'AccentColorDark';
