				end
				if #settings > visibleCount then
					Library:Create("TextLabel", {
						BackgroundTransparency = 1,
						FontFace = Library.Font,
						Position = UDim2.fromOffset(6, 27 + visibleCount * rowHeight),
						Size = UDim2.new(1, -12, 0, rowHeight),
