				Library:SafeCallback(Toggle.Callback, Toggle.Value);
				Library:SafeCallback(Toggle.Changed, Toggle.Value);

				aztup_options.OnlyShowEnabledKeybinds.__internal:fire()
			end)
			Toggle.__internal:fire(Toggle.Value)
			Library:UpdateDependencyBoxes();
		end;

		ToggleRegion.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				Toggle:SetValue(not Toggle.Value)
				Library:AttemptSave();
			elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then
				showModuleSettings(Input)
			end;
		end);
		ToggleLabel.InputBegan:Connect(showModuleSettings)

		if Toggle.Risky then
			Library:RemoveFromRegistry(ToggleLabel)
			ToggleLabel.TextColor3 = Library.RiskColor
			Library:AddToRegistry(ToggleLabel, { TextColor3 = 'RiskColor' })
		end

		Toggle:Display();
		if type(Info.Text) == 'string' and Info.Text ~= '' then
			Library:RegisterSearchEntry(Groupbox, {
				Kind = 'Toggle';
				Text = Info.Text;
				Tab = Groupbox.Tab or Groupbox;
				Target = ToggleOuter;
				Focus = function()
					Library:FocusSearchTarget(ToggleOuter)
				end;
			})
		end
		Groupbox:AddBlank(Info.BlankSize or 5 + 2);
		Groupbox:Resize();

		Toggle.TextLabel = ToggleLabel;
		Toggle.Container = Container;
		setmetatable(Toggle, BaseAddons or {})

		aztup_toggles[Idx] = Toggle;

		Library:UpdateDependencyBoxes();

		return Toggle	
end

	function Component.AddKeyPicker(self, Idx, Info)
		local ParentObj = self;
		local ToggleLabel = self.TextLabel;
		local Container = self.Container;
		
		
		

		assert(Info.Default, 'AddKeyPicker: Missing default value.');

		local KeyPicker: {[string]: any} = {
			Value = Info.Default;
			Toggled = false;
			Mode = Info.Mode or 'Toggle'; 
			Type = 'KeyPicker';
			Callback = Info.Callback or function(Value) end;
			ChangedCallback = Info.ChangedCallback or function(New) end;

			SyncToggleState = Info.SyncToggleState or false;
		};
		if ParentObj.Type == "Toggle" then
			ParentObj.ArrayListKeybindId = Idx
		end

		local Modes = Info.Modes or { 'Toggle', 'Hold' };

		self.KeyPicker = {
			Flag = Idx;
			Value = KeyPicker.Value
		}

		if not table.find(Modes, KeyPicker.Mode) then
			KeyPicker.Mode = Modes[1]
		end

		local ContainerLabelTransparencyTween
		local ContainerStrokeTransparencyTween

		local PickOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(0, 28, 0, 15);
			ZIndex = 6;
			Parent = ToggleLabel;
		});

		local PickInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 7;
			Parent = PickOuter;
		});

		Library:AddToRegistry(PickInner, {
			BackgroundColor3 = 'BackgroundColor';
			BorderColor3 = 'OutlineColor';
		});

		local DisplayLabel = Library:CreateLabel({
			Size = UDim2.new(1, 0, 1, 0);
			TextSize = 13;
			Text = Info.Default;
			TextWrapped = true;
			ZIndex = 8;
			Parent = PickInner;
			Name = "DisplayLabelKeybind";
		});
		DisplayLabel:SetAttribute("YSLBoldKeybind", true)
		DisplayLabel.FontFace = Font.fromEnum(Enum.Font.GothamBold)

		local ModeSelectOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.fromOffset(ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4, ToggleLabel.AbsolutePosition.Y + 1);
			Size = UDim2.new(0, 60, 0, (((#Modes)+1) * 15) + 2);
			Visible = false;
			ZIndex = 14;
			Parent = Library.ScreenGui;
		});

		Library:AddUIScale(ModeSelectOuter);

		ToggleLabel:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
			ModeSelectOuter.Position = UDim2.fromOffset(ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4, ToggleLabel.AbsolutePosition.Y + 1);
		end);

		local ModeSelectInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 15;
			Parent = ModeSelectOuter;
		});

		Library:AddToRegistry(ModeSelectInner, {
			BackgroundColor3 = 'BackgroundColor';
			BorderColor3 = 'OutlineColor';
		});

		Library:Create('UIListLayout', {
			FillDirection = Enum.FillDirection.Vertical;
			SortOrder = Enum.SortOrder.LayoutOrder;
			Parent = ModeSelectInner;
		});

		local ContainerLabel, ContainerStroke = Library:CreateLabel({
			Name = "HotkeyRow",
			TextXAlignment = Enum.TextXAlignment.Left;
			Size = UDim2.new(1, 0, 0, 30);
			TextSize = 14;
			TextYAlignment = Enum.TextYAlignment.Center;
			RichText = true;
			TextStrokeTransparency = 1;
			BackgroundColor3 = Library.BackgroundColor;
			BackgroundTransparency = Library.HudTransparency or 0.18;
			Visible = false;
			ZIndex = 110;
			Parent = Library.KeybindContainer;
		}, true);
		Library:Create("UICorner", {
			CornerRadius = UDim.new(0, 6),
			Parent = ContainerLabel,
		})
		local keyBadge = Library:Create("Frame", {
			Name = "HotkeyKeyBadge",
			BackgroundColor3 = Library.MainColor,
			BackgroundTransparency = 0.08,
			BorderSizePixel = 0,
			Position = UDim2.fromOffset(7, 5),
			Size = UDim2.fromOffset(30, 20),
			ZIndex = 111,
			Parent = ContainerLabel,
		})
		Library:AddToRegistry(keyBadge, {
			BackgroundColor3 = "MainColor",
		}, true)
		Library:Create("UICorner", {
			CornerRadius = UDim.new(0, 4),
			Parent = keyBadge,
		})
		local keyBadgeLabel = Library:CreateLabelNoStroke({
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			Text = "",
			TextSize = 11,
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextXAlignment = Enum.TextXAlignment.Center,
			TextYAlignment = Enum.TextYAlignment.Center,
			TextStrokeTransparency = 1,
			ZIndex = 112,
			Parent = keyBadge,
		}, true, lexend.bold)
		keyBadgeLabel:SetAttribute("YSLBoldKeybind", true)
		keyBadgeLabel.FontFace = Font.fromEnum(Enum.Font.GothamBold)
		local modeBadge = Library:Create("Frame", {
			Name = "HotkeyModeBadge",
			AnchorPoint = Vector2.new(1, 0.5),
			BackgroundColor3 = Library.MainColor,
			BackgroundTransparency = 0.08,
			BorderSizePixel = 0,
			Position = UDim2.new(1, -7, 0.5, 0),
			Size = UDim2.fromOffset(52, 18),
			ZIndex = 111,
			Parent = ContainerLabel,
		})
		Library:AddToRegistry(modeBadge, {
			BackgroundColor3 = "MainColor",
		}, true)
		Library:Create("UICorner", {
			CornerRadius = UDim.new(0, 8),
			Parent = modeBadge,
		})
		local modeBadgeLabel = Library:CreateLabelNoStroke({
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			Text = "",
			TextSize = 9,
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextXAlignment = Enum.TextXAlignment.Center,
			TextYAlignment = Enum.TextYAlignment.Center,
			TextStrokeTransparency = 1,
			ZIndex = 112,
			Parent = modeBadge,
		}, true, lexend.bold)
		modeBadgeLabel.FontFace = Font.fromEnum(Enum.Font.GothamBold)
		Library:AddToRegistry(modeBadgeLabel, {
			TextColor3 = "FontColor",
		}, true)
		local actionLabel = Library:CreateLabel({
			BackgroundTransparency = 1,
			Position = UDim2.fromOffset(50, 0),
			Size = UDim2.new(1, -108, 1, 0),
			Text = "",
			TextSize = 14,
			TextTruncate = Enum.TextTruncate.AtEnd,
			TextXAlignment = Enum.TextXAlignment.Left,
			TextYAlignment = Enum.TextYAlignment.Center,
			TextStrokeTransparency = 1,
			ZIndex = 111,
			Parent = ContainerLabel,
		}, true, lexend.regular)
		Library:AddToRegistry(actionLabel, {
			TextColor3 = "FontColor",
		}, true)
		local labelStroke = ContainerStroke
		labelStroke.Color = Library.OutlineColor
		labelStroke.Transparency = 0.4
		Library:AddToRegistry(labelStroke, {
			Color = function()
				return KeyPicker:GetState() and Library.AccentColor or Library.OutlineColor
			end,
		}, true)

		local function escapeRichText(value)
			return tostring(value):gsub('&', '&amp;'):gsub('<', '&lt;'):gsub('>', '&gt;')
		end
		
		task.spawn(function()
			ContainerLabel.FontFace = lexend.regular;
		end);

		local ModeButtons = {};

		for Idx, Mode in next, Modes do
			local ModeButton = {};

			local Label = Library:CreateLabel({
				Active = false;
				Size = UDim2.new(1, 0, 0, 15);
				TextSize = 13;
				Text = Mode;
				ZIndex = 16;
				Parent = ModeSelectInner;
			});

			function ModeButton:Select()
				for _, Button in next, ModeButtons do
					Button:Deselect();
				end;

				KeyPicker.Mode = Mode;

				Label.TextColor3 = Library.AccentColor;
				Library.RegistryMap[Label].Properties.TextColor3 = 'AccentColor';
				curr_mode_select = nil;
				ModeSelectOuter.Visible = false;
			end;

			function ModeButton:Deselect()
				KeyPicker.Mode = nil;

				Label.TextColor3 = Library.FontColor;
				Library.RegistryMap[Label].Properties.TextColor3 = 'FontColor';
			end;

			Label.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					ModeButton:Select();
					Library:AttemptSave();
				end;
			end);

			if Mode == KeyPicker.Mode then
				ModeButton:Select();
			end;

			ModeButtons[Mode] = ModeButton;
		end;

		(function()

			local ModeButton = {};

			local Label = Library:CreateLabel({
				Active = false;
				Size = UDim2.new(1, 0, 0, 15);
				TextSize = 13;
				Text = "Unbind";
				ZIndex = 16;
				Parent = ModeSelectInner;
			});

			function ModeButton:Deselect() end;

			function ModeButton:Select()
				local Key = "None";
				
				DisplayLabel.Text = Key == "None" and "N/A" or Key;
				KeyPicker.Value = Key;
				Library:SafeCallback(KeyPicker.ChangedCallback, Enum.KeyCode.Unknown)
				if KeyPicker.Changed then
					Library:SafeCallback(KeyPicker.Changed, Enum.KeyCode.Unknown)
				end;
				curr_mode_select = nil;
				ModeSelectOuter.Visible = false;
				Library:AttemptSave();
			end;

			Label.InputBegan:Connect(function(Input)
				if Input.UserInputType == Enum.UserInputType.MouseButton1 then
					ModeButton:Select();
					Library:AttemptSave();
				end;
			end);

			ModeButtons.Unbind = ModeButton;
		end)();

		local function UpdateKeybindFrameSize()
			Library.KeybindFrameResizeQueued = false

			if Info.NoUI or not Library.KeybindContainer or not Library.KeybindFrame then
				return
			end

			local YSize = 0
			local XSize = 0
			for _, Label in next, Library.KeybindContainer:GetChildren() do
				if Label:IsA('TextLabel') then
					if Label.Visible and not Label:GetAttribute('KeybindFadingOut') then
						YSize = YSize + 30
					end

					local scale = Library:GetUIScale()
					local action = Label:FindFirstChildWhichIsA("TextLabel")
					local badge = Label:FindFirstChild("HotkeyKeyBadge")
					local modeBadge = Label:FindFirstChild("HotkeyModeBadge")
					local LabelWidth = action
						and Library:GetLexendTextBounds(action.Text, lexend.regular, 14) / scale
						or 0
					LabelWidth += badge and badge.AbsoluteSize.X / scale or 0
					LabelWidth += modeBadge and modeBadge.AbsoluteSize.X / scale or 0
					LabelWidth += 56
					if Label.Visible and (LabelWidth > XSize) then
						XSize = LabelWidth
					end
				end
			end

			local NewHeight = YSize == 0 and 38 or YSize + 40
			local NewWidth = math.max(XSize + 24, 250)
			local properties = {
				Size = UDim2.new(0, NewWidth, 0, NewHeight);
			}

			if Library.KeybindFrameResizeTween then
				Library.KeybindFrameResizeTween:Cancel()
				Library.KeybindFrameResizeTween = nil
			end

			local tweenInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
			local Tween = services.TweenService:Create(Library.KeybindFrame, tweenInfo, properties)
			Library.KeybindFrameResizeTween = Tween

			Tween.Completed:Connect(function()
				if Library.KeybindFrameResizeTween == Tween then
					Library.KeybindFrameResizeTween = nil
				end
			end)

			Tween:Play()
		end

		local function QueueKeybindFrameSize()
			if Library.KeybindFrameResizeQueued then
				return
			end

			Library.KeybindFrameResizeQueued = true
			task.defer(UpdateKeybindFrameSize)
		end

		function KeyPicker:Update()
		    if Info.NoUI then return end

		    local State = KeyPicker:GetState()
		    local shouldHide = (not State and aztup_toggles.OnlyShowEnabledKeybinds and aztup_toggles.OnlyShowEnabledKeybinds.Value)
		                   or (KeyPicker.Value == "None")

			if Info.KeybindOnly then
				State = false;
				shouldHide = (KeyPicker.Value == "None")
			end;

			if #tostring(KeyPicker.Value) == 0 then
			   	shouldHide = true
			end;

		    
			local actionText = escapeRichText(Info.Text)
			local keyWidth = math.clamp(
				Library:GetLexendTextBounds(KeyPicker.Value, lexend.bold, 11) + 14,
				30,
				72
			)
			keyBadge.Size = UDim2.fromOffset(keyWidth, 18)
			keyBadgeLabel.Text = KeyPicker.Value
			local modeText = State and "ACTIVE" or string.upper(tostring(KeyPicker.Mode or "TOGGLE"))
			modeBadgeLabel.Text = modeText
			modeBadge.BackgroundColor3 = State and Library.AccentColorDark or Library.MainColor
			modeBadgeLabel.TextColor3 = Library.FontColor
			Library.RegistryMap[modeBadge].Properties.BackgroundColor3 = State
				and function()
					return Library.AccentColorDark
				end
				or "MainColor"
			Library.RegistryMap[modeBadgeLabel].Properties.TextColor3 = "FontColor"
			keyBadge.BackgroundColor3 = State and Library.AccentColorDark or Library.MainColor
			keyBadgeLabel.TextColor3 = State and Library.FontColor or Library.AccentColor
			Library.RegistryMap[keyBadge].Properties.BackgroundColor3 = State
				and function()
					return Library.AccentColorDark
				end
				or "MainColor"
			Library.RegistryMap[keyBadgeLabel].Properties.TextColor3 = State and "FontColor" or "AccentColor"
			ContainerLabel.Text = ""
			actionLabel.Text = actionText
			actionLabel.Position = UDim2.fromOffset(keyWidth + 14, 0)
			actionLabel.Size = UDim2.new(1, -(keyWidth + 78), 1, 0)
		    local x, _ = Library:GetLexendTextBounds(string.format('[%s]  %s', KeyPicker.Value, Info.Text), lexend.regular, 14)
		    ContainerLabel.LayoutOrder = -x
		    actionLabel.TextColor3 = State and Library.AccentColor or Library.FontColor
		    Library.RegistryMap[actionLabel].Properties.TextColor3 = State and 'AccentColor' or 'FontColor'
			ContainerLabel.BackgroundColor3 = Library.BackgroundColor
			ContainerLabel.BackgroundTransparency = Library.HudTransparency or 0.18
			Library.RegistryMap[ContainerLabel].Properties.BackgroundColor3 = "BackgroundColor"

		    if shouldHide then
		        
		        if ContainerLabel.Visible and not ContainerLabel:GetAttribute('KeybindFadingOut') then
		            if ContainerLabelTransparencyTween then
		                ContainerLabelTransparencyTween:Cancel()
		                ContainerLabelTransparencyTween = nil
		            end

		            if ContainerStrokeTransparencyTween then
		                ContainerStrokeTransparencyTween:Cancel()
		                ContainerStrokeTransparencyTween = nil
		            end

		            ContainerLabel:SetAttribute('KeybindFadingOut', true)

		            local fadeOut = services.TweenService:Create(actionLabel, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                TextTransparency = 1
		            })
		            ContainerLabelTransparencyTween = fadeOut
		            fadeOut:Play()

				local strokeFadeOut = services.TweenService:Create(ContainerStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                Transparency = 1
				})
				ContainerStrokeTransparencyTween = strokeFadeOut
				strokeFadeOut:Play()
				fadeOut.Completed:Connect(function(playbackState)
					if ContainerLabelTransparencyTween ~= fadeOut then
						return
					end

					ContainerLabelTransparencyTween = nil
					ContainerStrokeTransparencyTween = nil

						if playbackState ~= Enum.PlaybackState.Completed or not ContainerLabel.Visible or KeyPicker:GetState() then
						ContainerLabel:SetAttribute('KeybindFadingOut', nil)
							return
						end

						ContainerLabel.Visible = false
					ContainerLabel:SetAttribute('KeybindFadingOut', nil)
						KeyPicker:Update()
		            end)
		        end
		        
		    else
				if ContainerLabel:GetAttribute('KeybindFadingOut') then
					ContainerLabel:SetAttribute('KeybindFadingOut', nil)
				end

				if ContainerLabelTransparencyTween then
					ContainerLabelTransparencyTween:Cancel()
					ContainerLabelTransparencyTween = nil
				end

				if ContainerStrokeTransparencyTween then
					ContainerStrokeTransparencyTween:Cancel()
					ContainerStrokeTransparencyTween = nil
				end

		        
		        if not ContainerLabel.Visible then
		            ContainerLabel.Visible = true
		            actionLabel.TextTransparency = 1
		            ContainerStroke.Transparency = 1
		            local fadeIn = services.TweenService:Create(actionLabel, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                TextTransparency = 0
		            })
		            ContainerLabelTransparencyTween = fadeIn
		            fadeIn:Play()
					
				local strokeFadeIn = services.TweenService:Create(ContainerStroke, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
		                Transparency = 0
				})
				ContainerStrokeTransparencyTween = strokeFadeIn
				strokeFadeIn:Play()
		        else
		            
					ContainerStroke.Transparency = 0
		            actionLabel.TextTransparency = 0
		        end
		    end

			Library.RegistryMap[ContainerLabel].KEYBINDLABEL = true;
			Library.RegistryMap[actionLabel].Properties.TextColor3 = State and 'AccentColor' or 'FontColor';

			QueueKeybindFrameSize()
			if ParentObj.Type == "Toggle" and Library.ArrayListController then
				Library.ArrayListController:Refresh()
			end
		end;

		function KeyPicker:GetState()
			if KeyPicker.Mode == 'Always' then
				return true			
elseif KeyPicker.Mode == 'Hold' then
				if KeyPicker.Value == 'None' then
					return false				
end

				local Key = KeyPicker.Value;

				if Key == 'MB1' or Key == 'MB2' then
					return Key == 'MB1' and InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
						or Key == 'MB2' and InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)				
else
					return InputService:IsKeyDown(Enum.KeyCode[KeyPicker.Value])				
end;
			else
				return KeyPicker.Toggled			
end;
		end;

		function KeyPicker:SetValue(Data)
			local Key, Mode = Data[1], Data[2];
			DisplayLabel.Text = Key == "None" and "N/A" or Key;
			KeyPicker.Value = Key;
			ModeButtons[Mode]:Select();
			KeyPicker:Update();
		end;

		function KeyPicker:OnClick(Callback)
			KeyPicker.Clicked = Callback
		end

		function KeyPicker:OnChanged(Callback)
			KeyPicker.Changed = Callback
			Callback(KeyPicker.Value)
		end

		if ParentObj.Addons then
			table.insert(ParentObj.Addons, KeyPicker)
		end

		function KeyPicker:DoClick()
			if ParentObj.Type == 'Toggle' and KeyPicker.SyncToggleState then
				if KeyPicker.Mode == 'Hold' then
					ParentObj:SetValue(KeyPicker.Toggled)
				else
					ParentObj:SetValue(not ParentObj.Value)
				end
			end

			Library:SafeCallback(KeyPicker.Callback, KeyPicker.Toggled)
			Library:SafeCallback(KeyPicker.Clicked, KeyPicker.Toggled)
			self:Update()
		end

		local Picking = false;

		PickOuter.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				xpcall(function()
					Picking = true;
					DisplayLabel.Text = '';
					local Break;
					local Text = '';
					task.spawn(function()
						pcall(function()
							while (not Break) do
								if Text == '...' then
									Text = '';
								end;
								Text = Text .. '.';
								DisplayLabel.Text = Text;
								task.wait(0.4);
							end;
						end)
					end);
					task.wait(0.2);
					local Event;
					Event = InputService.InputBegan:Connect(function(Input)
						local Key;
						local kc = Input.KeyCode;
						if Input.UserInputType == Enum.UserInputType.Keyboard then
							Key = Input.KeyCode.Name;
							if kc == Enum.KeyCode.Backspace or kc == Enum.KeyCode.Escape then
								Key = 'None'
								kc = Enum.KeyCode.Unknown;
							end;
						elseif Input.UserInputType == Enum.UserInputType.MouseButton1 then
							Key = 'MB1';
						elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then
							Key = 'MB2';
						end;
						Break = true;
						Picking = false;

						Event:Disconnect();
						DisplayLabel.Text = Key == "None" and "N/A" or Key;
						KeyPicker.Value = Key;
						Library:SafeCallback(KeyPicker.ChangedCallback, kc or Input.UserInputType)
						Library:SafeCallback(KeyPicker.Changed, kc or Input.UserInputType)
						Library:AttemptSave();
					end);
				end, print);
			elseif Input.UserInputType == Enum.UserInputType.MouseButton2 and not Library:MouseIsOverOpenedFrame() then
				if curr_mode_select then
					curr_mode_select.Visible = false;
					curr_mode_select = nil;
				end

				curr_mode_select = ModeSelectOuter;
				ModeSelectOuter.Visible = true;
			end;
		end);

		local function IsBoundInput(Input, Processed)
			local Key = KeyPicker.Value;

			if Key == 'None' then
				return false
			end

			if Key == 'MB1' then
				return Input.UserInputType == Enum.UserInputType.MouseButton1
		elseif Key == 'MB2' then
				return Input.UserInputType == Enum.UserInputType.MouseButton2
		end

			return Input.UserInputType == Enum.UserInputType.Keyboard and not Processed and Input.KeyCode.Name == Key
		end

		local function IsBoundInputEnded(Input)
			local Key = KeyPicker.Value;

			if Key == 'None' then
				return false
			end

			if Key == 'MB1' then
				return Input.UserInputType == Enum.UserInputType.MouseButton1
			elseif Key == 'MB2' then
				return Input.UserInputType == Enum.UserInputType.MouseButton2
			end

			return Input.UserInputType == Enum.UserInputType.Keyboard and Input.KeyCode.Name == Key
		end

		Library:GiveSignal(InputService.InputBegan:Connect(function(Input,t)
			if (not Picking) then
				if KeyPicker.Mode == 'Toggle' then
					if IsBoundInput(Input, t) then
						KeyPicker.Toggled = not KeyPicker.Toggled
						KeyPicker:DoClick();
						KeyPicker:Update();
					end;
				elseif KeyPicker.Mode == 'Hold' then
					if IsBoundInput(Input, t) then
						if not KeyPicker.Toggled then
							KeyPicker.Toggled = true
							KeyPicker:DoClick();
						end
						KeyPicker:Update();
					end
				end;
			end;

			if not Library.Toggled then
				return			
end;
			if Input.UserInputType == Enum.UserInputType.MouseButton1 then
				local AbsPos, AbsSize = ModeSelectOuter.AbsolutePosition, ModeSelectOuter.AbsoluteSize;

				if Mouse.X < AbsPos.X or Mouse.X > AbsPos.X + AbsSize.X
					or Mouse.Y < (AbsPos.Y - 20 - 1) or Mouse.Y > AbsPos.Y + AbsSize.Y then
					curr_mode_select = nil;
					ModeSelectOuter.Visible = false;
				end;
			end;
		end))

		Library:GiveSignal(InputService.InputEnded:Connect(function(Input)
			if (not Picking) then
				if KeyPicker.Mode == 'Hold' and KeyPicker.Toggled and IsBoundInputEnded(Input) then
					KeyPicker.Toggled = false
					KeyPicker:DoClick();
				end
			end;
		end))

		loaded_signal:connect(function()
			KeyPicker:Update()
		end)
		KeyPicker:Update();

		aztup_options[Idx] = KeyPicker;

		return self	
end

	return Component
end
	end,
	["@src/ui/ambience"] = function()
local RunService = game:GetService("RunService")
local Random = Random.new()

return function(library)
	local particles = {}
	local layer = library:Create("Frame", {
		Name = "InterfaceAmbience",
		Active = false,
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Position = UDim2.fromScale(0, 0),
		Size = UDim2.fromScale(1, 1),
		Visible = false,
		ZIndex = 0,
		Parent = library.ScreenGui,
	})

	local mode = "Off"
	local intensity = 36

	for index = 1, 48 do
		local particle = library:Create("Frame", {
			AnchorPoint = Vector2.new(0.5, 0.5),
			BackgroundColor3 = library.FontColor,
			BackgroundTransparency = 0.12,
			BorderSizePixel = 0,
			Visible = false,
			ZIndex = 0,
			Parent = layer,
		})
		library:AddToRegistry(particle, {
			BackgroundColor3 = function()
				return mode == "Rain" and library.AccentColor or library.FontColor
			end,
		})
		local corner = library:Create("UICorner", {
			CornerRadius = UDim.new(1, 0),
			Parent = particle,
		})

		particles[index] = {
			Instance = particle,
			Corner = corner,
			X = 0,
			Y = 0,
			Speed = 0,
			Drift = 0,
			Phase = Random:NextNumber(0, math.pi * 2),
			Size = 0,
		}
	end

	local function configureParticle(state, width, height, initial)
		local isRain = mode == "Rain"
		state.Size = isRain and 2 or Random:NextNumber(4, 8)
		state.X = Random:NextNumber(0, math.max(1, width))
		state.Y = initial and Random:NextNumber(0, math.max(1, height)) or -state.Size
		state.Speed = isRain and Random:NextNumber(420, 620) or Random:NextNumber(24, 58)
		state.Drift = isRain and -state.Speed * math.tan(math.rad(12))
			or Random:NextNumber(-12, 12)

		local particle = state.Instance
		particle.Size = isRain and UDim2.fromOffset(2, Random:NextNumber(18, 30)) or UDim2.fromOffset(state.Size, state.Size)
		particle.Rotation = isRain and 12 or 0
		particle.BackgroundTransparency = isRain and 0.18 or 0.08
		particle.Visible = true
	end

	local function refreshVisibility()
		local visible = mode ~= "Off" and library.Toggled == true
		layer.Visible = visible
		local width, height = layer.AbsoluteSize.X, layer.AbsoluteSize.Y
		local precipitation = mode == "Rain" or mode == "Snow"
		for index, state in ipairs(particles) do
			local particleVisible = visible and precipitation and index <= intensity
			state.Instance.Visible = particleVisible
			if particleVisible and (state.Instance.Size.X.Offset == 0 or state.Y == 0) then
				configureParticle(state, width, height, true)
			end
		end
	end

	local controller = {}
	function controller:SetMode(value)
		if value ~= "Off" and value ~= "Rain" and value ~= "Snow" then
			return false
		end
		mode = value
		for _, state in ipairs(particles) do
			state.Y = 0
			state.Instance.Visible = false
		end
		refreshVisibility()
		library:UpdateColorsUsingRegistry()
		return true
	end

	function controller:SetIntensity(value)
		intensity = math.clamp(math.floor(tonumber(value) or intensity), 8, #particles)
		refreshVisibility()
	end

	library:GiveSignal(library.OnToggledChanged.Event:Connect(refreshVisibility))
	library:GiveSignal(layer:GetPropertyChangedSignal("AbsoluteSize"):Connect(refreshVisibility))
	library:GiveSignal(RunService.RenderStepped:Connect(function(deltaTime)
		if not layer.Visible then
			return
		end

		local width, height = layer.AbsoluteSize.X, layer.AbsoluteSize.Y
		for index = 1, intensity do
			local state = particles[index]
			state.Y += state.Speed * deltaTime
			state.X += state.Drift * deltaTime
			if mode == "Snow" then
				state.X += math.sin(os.clock() + state.Phase) * 9 * deltaTime
			end
			if state.Y > height + state.Size or state.X < -8 or state.X > width + 8 then
				configureParticle(state, width, height, false)
			else
				state.Instance.Position = UDim2.fromOffset(state.X, state.Y)
			end
		end
	end))
	library:GiveSignal(library.ScreenGui.DescendantRemoving:Connect(function(instance)
		if instance == layer then
			layer.Visible = false
		end
	end))

	return controller
end
	end,
	["@src/ui/arraylist"] = function()
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local UserInputService = game:GetService("UserInputService")

return function(library)
	local gradientEnabled = true
	local gradientDuration = 5
	local visible = false
	local backgroundEnabled = true
	local textSize = 18
	local lastColorRefresh = 0
	local labels = {}
	local rowsById = {}
	local exitingRows = {}
	local leftSide = true
	local bottomSide = false
	local dragging = false
	local refresh

	local panel = library:Create("Frame", {
		Name = "YSLArrayList",
		Active = true,
		AnchorPoint = Vector2.new(1, 0),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.new(1, -8, 0, 88),
		Size = UDim2.fromOffset(240, 20),
		Visible = false,
		ZIndex = 80,
		Parent = library.ScreenGui,
	})
	library.ArrayListFrame = panel
	library:MakeDraggable(panel, 16, true)
	panel.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = true
		end
	end)

	local function updatePlacement()
		local absolutePosition = panel.AbsolutePosition
		local absoluteSize = panel.AbsoluteSize
		local center = absolutePosition + absoluteSize * 0.5
		local camera = workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize
		if not viewport then
			return
		end

		local newLeftSide = center.X < viewport.X * 0.5
		local newBottomSide = center.Y > viewport.Y * 0.5
		local changed = newLeftSide ~= leftSide or newBottomSide ~= bottomSide
		leftSide = newLeftSide
		bottomSide = newBottomSide
		panel.AnchorPoint = Vector2.new(leftSide and 0 or 1, bottomSide and 1 or 0)
		library.ArrayListAnchorPoint = panel.AnchorPoint
		panel.Position = UDim2.fromOffset(
			leftSide and absolutePosition.X or absolutePosition.X + absoluteSize.X,
			bottomSide and absolutePosition.Y + absoluteSize.Y or absolutePosition.Y
		)
		if changed then
			refresh()
		end
	end

	library:GiveSignal(UserInputService.InputEnded:Connect(function(input)
		if dragging and input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = false
			updatePlacement()
		end
	end))

	local list = library:Create("Frame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 16),
		Size = UDim2.new(1, 0, 1, -16),
		ZIndex = 80,
		Parent = panel,
	})
	local layout = library:Create("UIListLayout", {
		Padding = UDim.new(0, 0),
		SortOrder = Enum.SortOrder.LayoutOrder,
		VerticalAlignment = Enum.VerticalAlignment.Top,
		Parent = list,
	})

	local function getGradientColor(position)
		local dark = library.AccentColorDark or library:GetDarkerColor(library.AccentColor)
		position = position % 1
		local section = position * 4
		local index = math.floor(section)
		local blend = section - index
		blend = blend * blend * (3 - 2 * blend)
		if index == 0 then
			return library.AccentColor:Lerp(library.FontColor, blend)
		elseif index == 1 then
			return library.FontColor:Lerp(dark, blend)
		elseif index == 2 then
			return dark:Lerp(library.FontColor, blend)
		end
		return library.FontColor:Lerp(library.AccentColor, blend)
	end

	local function refreshColors()
		local count = #labels
		local phase = gradientEnabled and ((os.clock() / gradientDuration) % 1) or 0
		for index, entry in ipairs(labels) do
			local color
			if gradientEnabled then
				local rowPosition = count <= 1 and 0.5 or (index - 1) / (count - 1)
				color = getGradientColor((rowPosition + phase) % 1)
			else
				color = library.AccentColor
			end
			entry.Label.TextColor3 = color
			local nameText = string.format(
				'<font color="#%s">%s</font>',
				color:ToHex(),
				entry.EscapedName
			)
			local detailText = entry.EscapedDetail ~= ""
				and string.format(
					'  <font color="#%s">%s</font>',
					library.FontColor:ToHex(),
					entry.EscapedDetail
				)
				or ""
			entry.Label.Text = nameText .. detailText
			entry.Sidebar.BackgroundColor3 = color
		end
	end

	local function escapeRichText(text)
		return (text:gsub("&", "&amp;"):gsub("<", "&lt;"):gsub(">", "&gt;"))
	end

	local function createRow(entry, order, animateIn)
		local horizontalAnchor = leftSide and 0 or 1
		local textAlignment = leftSide and Enum.TextXAlignment.Left or Enum.TextXAlignment.Right
		local rowHeight = math.ceil(textSize * 1.36)
		local row = library:Create("Frame", {
			Active = true,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			LayoutOrder = order,
			Size = UDim2.new(1, 0, 0, animateIn and 0 or rowHeight),
			ZIndex = 81,
			Parent = list,
		})
		local background = library:Create("Frame", {
			Active = true,
			AnchorPoint = Vector2.new(horizontalAnchor, 0),
			BackgroundColor3 = Color3.new(0, 0, 0),
			BackgroundTransparency = animateIn and 1 or (backgroundEnabled and 0.25 or 1),
			BorderSizePixel = 0,
			Position = UDim2.new(horizontalAnchor, 0, 0, 0),
			Size = UDim2.fromOffset(entry.TextWidth + 12, rowHeight),
			ZIndex = 81,
			Parent = row,
		})
		local sidebar = library:Create("Frame", {
			Active = true,
			AnchorPoint = Vector2.new(horizontalAnchor, 0),
			BackgroundColor3 = library.AccentColor,
			BackgroundTransparency = animateIn and 1 or 0,
			BorderSizePixel = 0,
			Position = UDim2.new(horizontalAnchor, 0, 0, 0),
			Size = UDim2.new(0, 2, 1, 0),
			ZIndex = 83,
			Parent = row,
		})
		local label = library:CreateLabel({
			Active = true,
			AnchorPoint = Vector2.new(horizontalAnchor, 0),
			BackgroundTransparency = 1,
			Position = UDim2.new(horizontalAnchor, leftSide and 5 or -5, 0, 0),
			Size = UDim2.fromOffset(entry.TextWidth + 2, rowHeight),
			FontFace = lexend.bold,
			Text = entry.EscapedName,
			RichText = true,
			TextColor3 = Color3.new(1, 1, 1),
			TextSize = textSize,
			TextStrokeColor3 = Color3.new(0, 0, 0),
			TextStrokeTransparency = animateIn and 1 or 0.15,
			TextTransparency = animateIn and 1 or 0,
			TextXAlignment = textAlignment,
			ZIndex = 82,
			Parent = row,
		})
		library:AddToRegistry(label, {
			TextStrokeColor3 = "Black",
		})

		local result = {
			Id = entry.Id,
			Toggle = entry.Toggle,
			Row = row,
			Background = background,
			Label = label,
			EscapedName = entry.EscapedName,
			EscapedDetail = entry.EscapedDetail,
			TextWidth = entry.TextWidth,
			Sidebar = sidebar,
		}
		rowsById[entry.Id] = result
		local function handleRowInput(input)
			if input.UserInputType == Enum.UserInputType.MouseButton1 and result.Toggle.Value then
				result.Toggle:SetValue(false)
			end
		end
		row.InputBegan:Connect(handleRowInput)
		background.InputBegan:Connect(handleRowInput)
		sidebar.InputBegan:Connect(handleRowInput)
		label.InputBegan:Connect(handleRowInput)

		if animateIn then
			local tweenInfo = TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
			TweenService:Create(row, tweenInfo, {
				Size = UDim2.new(1, 0, 0, rowHeight),
			}):Play()
			TweenService:Create(background, tweenInfo, {
				BackgroundTransparency = backgroundEnabled and 0.25 or 1,
			}):Play()
			TweenService:Create(sidebar, tweenInfo, { BackgroundTransparency = 0 }):Play()
			TweenService:Create(label, tweenInfo, {
				TextTransparency = 0,
				TextStrokeTransparency = 0.15,
			}):Play()
		end
		return result
	end

	local function animateRemove(entry)
		if entry.Removing then
			return
		end
		entry.Removing = true
		rowsById[entry.Id] = nil
		exitingRows[entry.Id] = entry
		local tweenInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
		local tweens = {
			TweenService:Create(entry.Background, tweenInfo, {
				BackgroundTransparency = 1,
			}),
			TweenService:Create(entry.Sidebar, tweenInfo, {
				BackgroundTransparency = 1,
			}),
			TweenService:Create(entry.Label, tweenInfo, {
				TextTransparency = 1,
				TextStrokeTransparency = 1,
			}),
		}
		tweens[1].Completed:Connect(function()
			if entry.Row.Parent then
				entry.Row:Destroy()
			end
			if exitingRows[entry.Id] == entry then
				exitingRows[entry.Id] = nil
				if visible then
					refresh()
				end
			end
		end)
		for _, tween in ipairs(tweens) do
			tween:Play()
		end
	end

	refresh = function(changedToggle, changedValue)
		local active = {}
		local activeById = {}
		for id, toggle in pairs(aztup_toggles) do
			if toggle.Type == "Toggle" and toggle.Value and toggle.ArrayList ~= false
				and toggle.TabName ~= "Settings" then
				local details = {}
				if toggle.ArrayListKeybindId then
					local keybind = aztup_options[toggle.ArrayListKeybindId]
					if keybind and keybind.Value and keybind.Value ~= "None" then
						table.insert(details, "[" .. tostring(keybind.Value) .. "]")
					end
				end
				local detailText = table.concat(details, "  ")
				local text = toggle.Name .. (detailText ~= "" and "  " .. detailText or "")
				local textWidth = math.ceil(library:GetLexendTextBounds(text, lexend.bold, textSize))
				local entry = {
					Id = id,
					Toggle = toggle,
					Name = toggle.Name,
					DetailText = detailText,
					EscapedName = escapeRichText(toggle.Name),
					EscapedDetail = escapeRichText(detailText),
					TextLength = #text,
					TextWidth = textWidth,
				}
				table.insert(active, entry)
				activeById[id] = entry
			end
		end
		table.sort(active, function(left, right)
			if left.TextWidth ~= right.TextWidth then
				return left.TextWidth > right.TextWidth
			end
			if left.TextLength ~= right.TextLength then
				return left.TextLength > right.TextLength
			end
			local leftName = string.lower(left.Toggle.Name)
			local rightName = string.lower(right.Toggle.Name)
			if leftName == rightName then
				return tostring(left.Id) < tostring(right.Id)
			end
			return leftName < rightName
		end)
		layout.VerticalAlignment = Enum.VerticalAlignment.Top

		local rowHeight = math.ceil(textSize * 1.36)
		for id, row in pairs(rowsById) do
			if not activeById[id] then
				if changedToggle == row.Toggle and changedValue == false then
					animateRemove(row)
				else
					rowsById[id] = nil
					row.Row:Destroy()
				end
			end
		end

		table.clear(labels)
		local width = 0
		local exitingCount = 0
		local reservedOrders = {}
		for _, row in pairs(exitingRows) do
			exitingCount += 1
			reservedOrders[row.Row.LayoutOrder] = true
			width = math.max(width, row.TextWidth + 12)
		end
		local layoutOrder = 0
		for index, entry in ipairs(active) do
			width = math.max(width, entry.TextWidth + 12)
			layoutOrder += 1
			while reservedOrders[layoutOrder] do
				layoutOrder += 1
			end
			local row = rowsById[entry.Id]
			if row then
				row.Toggle = entry.Toggle
				row.Row.LayoutOrder = layoutOrder
				row.Row.Size = UDim2.new(1, 0, 0, rowHeight)
				row.Background.Size = UDim2.fromOffset(entry.TextWidth + 12, rowHeight)
				row.Background.BackgroundTransparency = backgroundEnabled and 0.25 or 1
				row.Label.Size = UDim2.fromOffset(entry.TextWidth + 2, rowHeight)
				row.TextWidth = entry.TextWidth
				row.EscapedName = entry.EscapedName
				row.EscapedDetail = entry.EscapedDetail
			else
				row = createRow(entry, layoutOrder, changedToggle == entry.Toggle and changedValue == true)
			end
			table.insert(labels, row)
		end

		panel.Size = UDim2.fromOffset(
			math.max(100, width + 4),
			16 + (#labels + exitingCount) * rowHeight
		)
		panel.Visible = visible and (#labels + exitingCount) > 0
		refreshColors()
	end

	local controller = {}
	function controller:SetVisible(value)
		visible = not not value
		refresh()
	end

	function controller:SetBackgroundEnabled(enabled)
		backgroundEnabled = not not enabled
		for _, entry in ipairs(labels) do
			entry.Background.BackgroundTransparency = backgroundEnabled and 0.25 or 1
		end
	end

	function controller:Refresh()
		refresh()
	end

	function controller:SetGradient(enabled, duration)
		gradientEnabled = not not enabled
		gradientDuration = math.clamp(tonumber(duration) or gradientDuration, 1, 12)
		refreshColors()
	end

	function controller:SyncPlacement()
		leftSide = panel.AnchorPoint.X < 0.5
		bottomSide = panel.AnchorPoint.Y > 0.5
		library.ArrayListAnchorPoint = panel.AnchorPoint
		refresh()
	end

	library.ArrayListAnchorPoint = panel.AnchorPoint
	library.ArrayListController = controller

	library:GiveSignal(library.ToggleChanged.Event:Connect(function(value, toggleId)
		if visible then
			local toggle = aztup_toggles[toggleId]
			refresh(toggle, value)
		end
	end))
	library:GiveSignal(RunService.RenderStepped:Connect(function()
		if not visible or not gradientEnabled or #labels == 0 then
			lastColorRefresh = 0
			return
		end
		local now = os.clock()
		if now - lastColorRefresh >= 1 / 15 then
			lastColorRefresh = now
			refreshColors()
		end
	end))
	library:GiveSignal(library.ScreenGui.Destroying:Connect(function()
		panel.Visible = false
	end))

	return controller
end
	end,
	["@src/ui/side_image"] = function()
local ContentProvider = game:GetService("ContentProvider")
local GuiService = game:GetService("GuiService")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local DEFAULT_ASSETS = {
	["Anime Girl 1"] = "115786328930349",
}
local DEFAULT_IMAGE_NAME = "Anime Girl 1"
local DEFAULT_IMAGE_SIZE = 400

return function(library)
	local sideImageScreenGui = Instance.new("ScreenGui")
	sideImageScreenGui.Name = "YSLMethodSideImages"
	sideImageScreenGui.DisplayOrder = library.ScreenGui.DisplayOrder - 1
	sideImageScreenGui.IgnoreGuiInset = library.ScreenGui.IgnoreGuiInset
	sideImageScreenGui.ResetOnSpawn = false
	sideImageScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
	sideImageScreenGui.Parent = library.ScreenGui.Parent
	library:OnUnload(function()
		sideImageScreenGui:Destroy()
	end)

	local container = library:Create("Frame", {
		Name = "YSL_SideImages",
		BackgroundTransparency = 1,
		ClipsDescendants = false,
		Size = UDim2.fromScale(1, 1),
		Position = UDim2.fromScale(0, 0),
		ZIndex = 1,
		Parent = sideImageScreenGui,
	})

	local images = {}
	local enabled = true
	local windowDragging = false

	local function getPointerPositions()
		local pointerPosition = UserInputService:GetMouseLocation()
		if library.ScreenGui.IgnoreGuiInset then
			return { pointerPosition }, { Vector2.zero }
		end
		local topLeftInset = GuiService:GetGuiInset()
		return { pointerPosition - topLeftInset, pointerPosition }, { topLeftInset, Vector2.zero }
	end

	local function containsPoint(image, point)
		local position = image.AbsolutePosition
		local size = image.AbsoluteSize
		return image.Visible and point.X >= position.X and point.X <= position.X + size.X
			and point.Y >= position.Y and point.Y <= position.Y + size.Y
	end

	local function updateWindowAnchoredImages()
		local window = library.WindowHolder
		if not window or not window.Parent then
			return
		end
		local scale = library:GetUIScale()
		local windowOrigin = (window.AbsolutePosition - container.AbsolutePosition) / scale
		local imageSize = window.AbsoluteSize.X / scale
		for _, image in pairs(images) do
			if image then
				image.Size = UDim2.fromOffset(imageSize, imageSize)
				image.Position = UDim2.fromOffset(windowOrigin.X, windowOrigin.Y - imageSize * 0.70)
			end
		end
	end

	local function getDefaultPosition(index)
		local window = library.WindowHolder
		if not window or not window.Parent then
			return UDim2.fromOffset(16 + (index - 1) * 36, 80)
		end

		local scale = library:GetUIScale()
		local windowOrigin = (window.AbsolutePosition - container.AbsolutePosition) / scale
		local imageSize = window.AbsoluteSize.X / scale
		return UDim2.fromOffset(windowOrigin.X, windowOrigin.Y - imageSize * 0.70)
	end

	local function preload(image)
		task.spawn(function()
			local success, err = pcall(function()
				ContentProvider:PreloadAsync({ image }, function(assetId, status)
					if status ~= Enum.AssetFetchStatus.Success then
						warn(string.format(
							"[YSL Method] Side image asset %s failed to load (%s).",
							tostring(assetId),
							tostring(status)
						))
					end
				end)
			end)
			if not success then
				warn("[YSL Method] Could not load side image asset: " .. tostring(err))
			end
		end)
	end

	local function ensureImage(name, index)
		local image = images[name]
		if image then
			return image
		end
		image = library:Create("ImageLabel", {
			Name = "YSL_SideImage_" .. name:gsub("%W", ""),
			Active = false,
			BackgroundTransparency = 1,
			BorderSizePixel = 0,
			Image = "rbxthumb://type=Asset&id=" .. DEFAULT_ASSETS[name] .. "&w=420&h=420",
			ScaleType = Enum.ScaleType.Fit,
			Size = UDim2.fromOffset(DEFAULT_IMAGE_SIZE, DEFAULT_IMAGE_SIZE),
			Position = getDefaultPosition(index),
			Visible = false,
			ZIndex = 1,
			Parent = container,
		})
		image.Rotation = 0
		library:AddUIScale(image)
		images[name] = image
		preload(image)
		return image
	end

	local function refresh()
		if not enabled or library.Toggled ~= true or windowDragging then
			for name, image in pairs(images) do
				image.Visible = false
			end
			return
		end
		for _, image in pairs(images) do
			image.Visible = true
		end
	end

	local controller = {}
	function controller:IsPointerOverImage()
		local pointerPositions = getPointerPositions()
		for _, image in pairs(images) do
			for _, pointerPosition in ipairs(pointerPositions) do
				if containsPoint(image, pointerPosition) then
					return true
				end
			end
		end
		return false
	end

	function controller:SetEnabled(value)
		enabled = value == true
		refresh()
	end

	function controller:SetSelection(value)
		ensureImage(DEFAULT_IMAGE_NAME, 1)
		refresh()
		return true
	end

	function controller:GetConfigState()
		return {
			assets = table.clone(DEFAULT_ASSETS),
		}
	end

	function controller:SetConfigState(state)
		if type(state) ~= "table" then
			return false
		end
		controller:SetSelection({ [DEFAULT_IMAGE_NAME] = true })
		updateWindowAnchoredImages()
		return true
	end

	library:GiveSignal(library.OnToggledChanged.Event:Connect(refresh))
	library:GiveSignal(library.WindowDraggingChanged.Event:Connect(function(isDragging)
		windowDragging = isDragging == true
		refresh()
	end))
	library:GiveSignal(library.ScreenGui:GetPropertyChangedSignal("AbsoluteSize"):Connect(refresh))
	library:GiveSignal(RunService.RenderStepped:Connect(function()
		updateWindowAnchoredImages()
	end))
	controller:SetSelection({ [DEFAULT_IMAGE_NAME] = true })
	return controller
end
