                            f.Name = "BossEnemy"; f.Parent = character
                            CollectionService:AddTag(f, "BossEnemy")
                            createdBossEnemies[character] = f
                        end
                    end
                end
            end
        else
            for character, bossEnemy in pairs(createdBossEnemies) do
                if bossEnemy and bossEnemy.Parent then bossEnemy:Destroy() end
            end
            createdBossEnemies = {}
        end
    end

    VisualTab:CreateToggle({
        Name = "Boss Bar (All Enemies)", CurrentValue = false, Flag = "BossBar",
        Callback = function(state) _G.BossBarToggle(state) end,
    })

    VisualTab:CreateSection("Fullbright")
    local fullbrightEnabled = false
    local fullbrightDefaults = {
        Ambient = Lighting.Ambient,
        Brightness = Lighting.Brightness,
        ClockTime = Lighting.ClockTime,
        FogEnd = Lighting.FogEnd,
        FogStart = Lighting.FogStart,
        GlobalShadows = Lighting.GlobalShadows,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale,
        EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale,
        ShadowSoftness = Lighting.ShadowSoftness,
    }
    local atmosphere = Lighting:FindFirstChildOfClass("Atmosphere")
    local atmosphereDefaults = atmosphere and {
        Density = atmosphere.Density, Offset = atmosphere.Offset,
        Glare = atmosphere.Glare, Haze = atmosphere.Haze,
    } or nil

    local fullbrightTarget = {
        Ambient = Color3.new(1, 1, 1), Brightness = 2, ClockTime = 14,
        FogEnd = 999999, FogStart = 0, GlobalShadows = false,
        OutdoorAmbient = Color3.new(1, 1, 1),
        EnvironmentDiffuseScale = 1, EnvironmentSpecularScale = 1,
        ShadowSoftness = 0,
    }
    local function applyFullbright()
        -- The game may change Lighting at runtime. Only repair changed fields.
        for property, value in pairs(fullbrightTarget) do
            if Lighting[property] ~= value then Lighting[property] = value end
        end
        local atmo = Lighting:FindFirstChildOfClass("Atmosphere")
        if atmo then
            if atmo.Density ~= 0 then atmo.Density = 0 end
            if atmo.Offset ~= 0 then atmo.Offset = 0 end
            if atmo.Glare ~= 0 then atmo.Glare = 0 end
            if atmo.Haze ~= 0 then atmo.Haze = 0 end
        end
    end

    local function restoreFullbright()
        for prop, value in pairs(fullbrightDefaults) do
            pcall(function() Lighting[prop] = value end)
        end
        local atmo = Lighting:FindFirstChildOfClass("Atmosphere")
        if atmo and atmosphereDefaults then
            for prop, value in pairs(atmosphereDefaults) do
                pcall(function() atmo[prop] = value end)
            end
        end
    end

    -- Reassert slowly in case the game changes Lighting; doing this every rendered
    -- frame was one of the script's largest avoidable idle costs.
    task.spawn(function()
        while true do
            task.wait(fullbrightEnabled and 0.5 or 1.5)
            if fullbrightEnabled then applyFullbright() end
        end
    end)

    VisualTab:CreateToggle({
        Name = "Fullbright", CurrentValue = false, Flag = "Fullbright",
        Callback = function(state)
            fullbrightEnabled = state
            if state then applyFullbright() else restoreFullbright() end
        end,
    })

    VisualTab:CreateButton({
        Name = "Remove Blood",
        Callback = function()
            local thrown = Workspace:FindFirstChild("Thrown")
            if thrown then
                for _, v in pairs(thrown:GetChildren()) do
                    if v.Name == "BloodOnGroundDecal" then v:Destroy() end
                end
            end
        end,
    })

    VisualTab:CreateSection("Damage Indicator")
    local dmgTracked = {}
    local dmgEnabled = false

    local function spawnDmgNum(target, amount)
        if not target or not target:FindFirstChild("Head") then return end
        local gui = Instance.new("BillboardGui")
        gui.Name = "DamageNumber"
        gui.Size = UDim2.new(0, 100, 0, 50)
        gui.StudsOffset = Vector3.new(0, 3, 0)
        gui.AlwaysOnTop = true; gui.LightInfluence = 0
        gui.Parent = target.Head
        local lbl = Instance.new("TextLabel", gui)
        lbl.Size = UDim2.new(1,0,1,0)
        lbl.BackgroundTransparency = 1; lbl.TextScaled = true
        lbl.Font = Enum.Font.GothamBold; lbl.TextStrokeTransparency = 0.5
        lbl.Text = tostring(math.floor(amount))
        lbl.TextColor3 = Color3.new(1,0,0)
        local xo = (math.random()*2-1)*2
        TweenService:Create(gui,TweenInfo.new(0.5,Enum.EasingStyle.Quad,Enum.EasingDirection.Out),
            {StudsOffset=Vector3.new(xo,5,0)}):Play()
        local tw2 = TweenService:Create(lbl,TweenInfo.new(0.5),{TextTransparency=1})
        tw2:Play(); tw2.Completed:Connect(function() gui:Destroy() end)
    end

    local function trackHum(hum, c)
        if dmgTracked[hum] then return end
        local record = {health = hum.Health}
        dmgTracked[hum] = record
        record.connection = hum:GetPropertyChangedSignal("Health"):Connect(function()
            if not dmgEnabled then return end
            local old = record.health
            local current = hum.Health
            local dmg = old - current
            if dmg > 0 and dmg < 1000 then spawnDmgNum(c, dmg) end
            record.health = current
        end)
    end

    VisualTab:CreateToggle({
        Name = "Damage Indicator", CurrentValue = false, Flag = "DamageIndicator",
        Callback = function(state)
            dmgEnabled = state
            if state then
                for _, obj in ipairs(Workspace:GetDescendants()) do
                    if obj:IsA("Humanoid") and obj.Parent and obj.Parent:IsA("Model") then
                        trackHum(obj, obj.Parent)
                    end
                end
            else
                for _, record in pairs(dmgTracked) do
                    if record.connection then record.connection:Disconnect() end
                end
                table.clear(dmgTracked)
            end
        end,
    })

    Workspace.DescendantAdded:Connect(function(obj)
        if dmgEnabled and obj:IsA("Humanoid") then
            task.wait(0.1)
            if obj.Parent and obj.Parent:IsA("Model") then trackHum(obj, obj.Parent) end
        end
    end)
end

-- ============================================================
-- ESP TAB
-- ============================================================
local ESPTab = VisualTab -- merged into Visuals

do
    local KrostinSettings = {
        Enabled=false, ShowBox=true, ShowHealth=true, ShowName=true, ShowDistance=false,
        Distance=2000, MaxHighlights=10, FontSize=13,
        BoxThickness=2, BoxBaseWidth=45, BoxBaseHeight=65,
        BoxColor=Color3.fromRGB(255,255,255),
        PlayerColor=Color3.fromRGB(0,120,255),
        NPCColor=Color3.fromRGB(255,0,0),
        HPColor=Color3.fromRGB(0,255,0),
        HealthBarWidth=4,
    }

    local ESPObjects = {}
    local espDrawFields = {"Box", "HealthBg", "Health", "HealthText", "Text"}

    local function removeESP(key)
        local data = ESPObjects[key]; if not data then return end
        if data.Connections then for _, c in ipairs(data.Connections) do pcall(c.Disconnect, c) end end
        for _, key in ipairs(espDrawFields) do
            local drawing = data[key]
            if drawing then
                -- Drawing objects must be removed, not just hidden, or NPC turnover leaks them.
                pcall(function()
                    if drawing.Remove then drawing:Remove()
                    elseif drawing.Destroy then drawing:Destroy() end
                end)
            end
        end
        if data.Highlight then pcall(data.Highlight.Destroy, data.Highlight) end
        ESPObjects[key] = nil
    end

    local function addEntityESP(entity)
        if ESPObjects[entity] or not entity:IsA("Model") then return end
        local hum = entity:FindFirstChildOfClass("Humanoid")
        local r = root(entity)
        if not hum or not r or hum.Health <= 0 then return end
        local isPlayer = Players:GetPlayerFromCharacter(entity) ~= nil
        local plrObj = isPlayer and Players:GetPlayerFromCharacter(entity) or nil
        local eName = plrObj and plrObj.Name or entity.Name
        local hlColor = isPlayer and KrostinSettings.PlayerColor or KrostinSettings.NPCColor

        local box = Drawing.new("Square"); box.Thickness = KrostinSettings.BoxThickness
        box.Filled = false; box.Color = KrostinSettings.BoxColor
        local healthBg = Drawing.new("Square"); healthBg.Filled = true
        healthBg.Color = Color3.fromRGB(30,30,30); healthBg.Thickness = 0
        local healthBar = Drawing.new("Square"); healthBar.Filled = true
        healthBar.Color = KrostinSettings.HPColor; healthBar.Thickness = 0
        local healthText = Drawing.new("Text"); healthText.Center = true
        healthText.Outline = true; healthText.Color = KrostinSettings.HPColor
        healthText.Size = KrostinSettings.FontSize - 1
        local nameText = Drawing.new("Text"); nameText.Center = true
        nameText.Outline = true; nameText.Color = KrostinSettings.BoxColor
        nameText.Size = KrostinSettings.FontSize

        local highlight = Instance.new("Highlight")
        highlight.FillColor = hlColor; highlight.OutlineColor = hlColor
        highlight.FillTransparency = 0.5; highlight.OutlineTransparency = 0.3
        highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        highlight.Parent = entity; highlight.Enabled = false

        local connections = {}
        table.insert(connections, hum.Died:Connect(function() removeESP(entity) end))
        table.insert(connections, entity.AncestryChanged:Connect(function()
            if not entity:IsDescendantOf(Workspace) then removeESP(entity) end
        end))

        ESPObjects[entity] = {
            Box=box, HealthBg=healthBg, Health=healthBar, HealthText=healthText,
            Text=nameText, Highlight=highlight,
            Hum=hum, Root=r, Name=eName, IsPlayer=isPlayer,
            Connections=connections,
        }
    end

    local lastHLUpdate = 0
    local espFrameAccumulator = 0
    local espWasEnabled = false
    RS.RenderStepped:Connect(function(dt)
        KrostinSettings.Enabled = S.ESPEnabled
        KrostinSettings.ShowBox = S.ESPShowBox
        KrostinSettings.ShowHealth = S.ESPShowHealth
        KrostinSettings.ShowName = S.ESPShowName
        KrostinSettings.ShowDistance = S.ESPShowDist
        KrostinSettings.Distance = S.ESPMaxDist

        if not KrostinSettings.Enabled then
            if espWasEnabled then
                for _, data in pairs(ESPObjects) do
                    for _, k in ipairs(espDrawFields) do
                        if data[k] then data[k].Visible = false end
                    end
                    if data.Highlight then data.Highlight.Enabled = false end
                end
            end
            espWasEnabled = false
            return
        end
        espWasEnabled = true
        espFrameAccumulator += dt
        if espFrameAccumulator < (1 / 30) then return end
        espFrameAccumulator = 0

        local myChar = LP.Character; local myRoot = myChar and root(myChar)
        if not myRoot then return end
        local myPos = myRoot.Position
        local candidates = {}

        for entity, data in pairs(ESPObjects) do
            if not entity.Parent then removeESP(entity); continue end
            local pos = data.Root and data.Root.Position
            if data.Hum and data.Hum.Health <= 0 then removeESP(entity); continue end
            if not pos then continue end
            local dist = (pos - myPos).Magnitude
            if dist <= KrostinSettings.Distance then
                table.insert(candidates, {entity=entity, data=data, dist=dist})
            else
                for _, k in ipairs(espDrawFields) do
                    if data[k] then data[k].Visible = false end
                end
                if data.Highlight then data.Highlight.Enabled = false end
            end
        end

        table.sort(candidates, function(a,b) return a.dist < b.dist end)

        local now = tick()
        if now - lastHLUpdate > 0.1 then
            lastHLUpdate = now
            for i, entry in ipairs(candidates) do
                local hl = entry.data.Highlight
                if hl then
                    if i <= KrostinSettings.MaxHighlights then
                        hl.Enabled = true
                        local col = entry.data.IsPlayer and KrostinSettings.PlayerColor or KrostinSettings.NPCColor
                        hl.FillColor = col; hl.OutlineColor = col
                    else hl.Enabled = false end
                end
            end
        end

        for _, entry in ipairs(candidates) do
            local data = entry.data; local dist = entry.dist
            local rootPos = data.Root.Position
            local scaleFactor = 100 / math.max(dist, 1)
            local boxW = math.clamp(KrostinSettings.BoxBaseWidth * scaleFactor, 20, 200)
            local boxH = math.clamp(KrostinSettings.BoxBaseHeight * scaleFactor, 30, 300)
            local screenPos, onScreen = Camera:WorldToViewportPoint(rootPos)
            if not onScreen then
                for _, k in ipairs(espDrawFields) do
                    if data[k] then data[k].Visible = false end
                end
                continue
            end
            local cx, cy = screenPos.X, screenPos.Y
            local boxX, boxY = cx - boxW*0.5, cy - boxH*0.5

            if KrostinSettings.ShowBox then
                data.Box.Visible = true; data.Box.Position = Vector2.new(boxX,boxY)
                data.Box.Size = Vector2.new(boxW, boxH)
            else data.Box.Visible = false end

            if KrostinSettings.ShowHealth then
                local pct = math.clamp(data.Hum.Health/data.Hum.MaxHealth,0,1)
                local bw = KrostinSettings.HealthBarWidth
                local bx = boxX - bw - 3; local fillH = boxH*pct
                data.HealthBg.Visible = true; data.HealthBg.Position = Vector2.new(bx,boxY)
                data.HealthBg.Size = Vector2.new(bw,boxH)
                data.Health.Visible = true; data.Health.Position = Vector2.new(bx,boxY+boxH-fillH)
                data.Health.Size = Vector2.new(bw, fillH)
                data.HealthText.Visible = true
                data.HealthText.Text = math.floor(data.Hum.Health) .. " HP"
                data.HealthText.Position = Vector2.new(cx, boxY+boxH+3)
            else
                data.HealthBg.Visible = false; data.Health.Visible = false; data.HealthText.Visible = false
            end

            local nameStr = ""
            if KrostinSettings.ShowName then nameStr = data.Name end
            if KrostinSettings.ShowDistance then
                nameStr = nameStr .. (nameStr ~= "" and " " or "") .. string.format("[%.0fm]", dist)
            end
            data.Text.Visible = nameStr ~= ""
            if nameStr ~= "" then
                data.Text.Text = nameStr
                data.Text.Position = Vector2.new(cx, boxY - KrostinSettings.FontSize - 3)
            end
        end
    end)

    local function scanAliveFolder()
        local al = alive()
        if al then
            if S.ESPEnabled then
                for _, obj in ipairs(al:GetChildren()) do
                    if obj:IsA("Model") and obj:FindFirstChildOfClass("Humanoid") and not isPlr(obj) then
                        addEntityESP(obj)
                    end
                end
            end
            al.ChildAdded:Connect(function(child)
                if not S.ESPEnabled then return end
                task.wait(0.5)
                if S.ESPEnabled and child:IsA("Model") and child:FindFirstChildOfClass("Humanoid") and not isPlr(child) then
                    addEntityESP(child)
                end
            end)
        end
    end

    local function watchPlayer(plr)
        if plr == LP then return end
        if S.ESPEnabled and plr.Character then addEntityESP(plr.Character) end
        plr.CharacterAdded:Connect(function(char)
            if not S.ESPEnabled then return end
            task.wait(1)
            if S.ESPEnabled then addEntityESP(char) end
        end)
    end

    for _, plr in ipairs(Players:GetPlayers()) do watchPlayer(plr) end
    Players.PlayerAdded:Connect(watchPlayer)

    task.spawn(function()
        while true do
            task.wait(S.ESPEnabled and 3 or 10)
            if S.ESPEnabled then
                local al = alive()
                if al then
                    for _, obj in ipairs(al:GetChildren()) do
                        if obj:IsA("Model") and obj:FindFirstChildOfClass("Humanoid") and not isPlr(obj) then
                            if not ESPObjects[obj] then addEntityESP(obj) end
                        end
                    end
                end
            end
        end
    end)

    task.defer(scanAliveFolder)

    ESPTab:CreateSection("ESP Settings")
    ESPTab:CreateToggle({ Name = "ESP", CurrentValue=false, Flag="ESP",
        Callback = function(state)
            S.ESPEnabled = state
            if not state then
                -- Reclaim all drawings when ESP is off; enable recreates as needed.
                while next(ESPObjects) do removeESP(next(ESPObjects)) end
            end
            if state then
                -- Populate tracked entities immediately instead of waiting for the slow scan.
                local al = alive()
                if al then
                    for _, obj in ipairs(al:GetChildren()) do
                        if obj:IsA("Model") and not isPlr(obj) then addEntityESP(obj) end
                    end
                end
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr ~= LP and plr.Character then addEntityESP(plr.Character) end
                end
            end
        end })
    ESPTab:CreateToggle({ Name = "Show Boxes", CurrentValue=true, Flag="ESPBox",
        Callback = function(state) S.ESPShowBox = state end })
    ESPTab:CreateToggle({ Name = "Show Health", CurrentValue=true, Flag="ESPHealth",
        Callback = function(state) S.ESPShowHealth = state end })
    ESPTab:CreateToggle({ Name = "Show Names", CurrentValue=true, Flag="ESPNames",
        Callback = function(state) S.ESPShowName = state end })
    ESPTab:CreateToggle({ Name = "Show Distance", CurrentValue=false, Flag="ESPDist",
        Callback = function(state) S.ESPShowDist = state end })
    ESPTab:CreateSlider({ Name = "Max Distance", Range={100,5000}, Increment=100,
        CurrentValue=2000, Flag="ESPMaxDist", Callback = function(v) S.ESPMaxDist = v end })
end

-- ============================================================
-- CHARACTER TAB
-- ============================================================
local CharTab = Window:CreateTab("Character", 10726204364)

do
    local ragdollConn = nil
    local staminaConn = nil
    local staminaValue = nil
    local staminaLast = nil
    local staminaWriting = false
    local dashConn = nil
    local dashWaitConn = nil
    local dashValue = nil
    local dashOriginal = nil
    local cooldownChildConn = nil
    local cooldownAttrConns = {}
    local fallRecords = setmetatable({}, {__mode = "k"})
    local ragTags = {Ragdolled=true, Ragdoll=true, IsRagdoll=true, KnockedDown=true, Stunned=true, DashDisabled=true}

    local function localCharacterModel()
        local al = alive()
        return (al and al:FindFirstChild(LP.Name)) or LP.Character
    end

    local function disconnect(conn)
        if conn then pcall(function() conn:Disconnect() end) end
    end

    -- Character movement uses the same simple BodyVelocity/BodyGyro pattern
    -- used by the other two source bases, but keeps exact collision state so
    -- turning Noclip off does not force every limb to CanCollide=true.
    local charFlyConn = nil
    local charFlyBV, charFlyBG = nil, nil
    local charFlyHumanoid = nil
    local charNoclipConn = nil
    local charNoclipAddedConn = nil
    local charNoclipCharacter = nil
    local charNoclipStates = setmetatable({}, {__mode = "k"})

    local function stopCharacterFly()
        disconnect(charFlyConn); charFlyConn = nil
        if charFlyBV then pcall(function() charFlyBV:Destroy() end); charFlyBV = nil end
        if charFlyBG then pcall(function() charFlyBG:Destroy() end); charFlyBG = nil end
        if charFlyHumanoid and charFlyHumanoid.Parent then
            pcall(function() charFlyHumanoid.PlatformStand = false end)
        end
        charFlyHumanoid = nil
    end

    local function startCharacterFly()
        stopCharacterFly()
        if not S.FlyEnabled then return end
        charFlyConn = RS.Heartbeat:Connect(function()
            if not S.FlyEnabled then return end
            local character = LP.Character
            local humanoid = character and character:FindFirstChildOfClass("Humanoid")
            local hrp = root(character)
            if not humanoid or not hrp then return end
            charFlyHumanoid = humanoid
            humanoid.PlatformStand = true

            if not charFlyBV or charFlyBV.Parent ~= hrp then
                if charFlyBV then pcall(function() charFlyBV:Destroy() end) end
                charFlyBV = Instance.new("BodyVelocity")
                charFlyBV.Name = "ArchivistFlyVelocity"
                charFlyBV.MaxForce = Vector3.new(1e5, 1e5, 1e5)
                charFlyBV.P = 1e4
                charFlyBV.Parent = hrp
            end
            if not charFlyBG or charFlyBG.Parent ~= hrp then
                if charFlyBG then pcall(function() charFlyBG:Destroy() end) end
                charFlyBG = Instance.new("BodyGyro")
                charFlyBG.Name = "ArchivistFlyGyro"
                charFlyBG.MaxTorque = Vector3.new(1e5, 1e5, 1e5)
                charFlyBG.P = 1e4
                charFlyBG.Parent = hrp
            end

            local camera = Workspace.CurrentCamera
            local direction = Vector3.zero
            if camera then
                if UIS:IsKeyDown(Enum.KeyCode.W) then direction += camera.CFrame.LookVector end
                if UIS:IsKeyDown(Enum.KeyCode.S) then direction -= camera.CFrame.LookVector end
                if UIS:IsKeyDown(Enum.KeyCode.D) then direction += camera.CFrame.RightVector end
                if UIS:IsKeyDown(Enum.KeyCode.A) then direction -= camera.CFrame.RightVector end
                if UIS:IsKeyDown(Enum.KeyCode.Space) then direction += Vector3.yAxis end
                if UIS:IsKeyDown(Enum.KeyCode.LeftShift) then direction -= Vector3.yAxis end
                charFlyBG.CFrame = camera.CFrame
            end
            charFlyBV.Velocity = direction.Magnitude > 0 and direction.Unit * S.FlySpeed or Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    local function stopCharacterNoclip()
        disconnect(charNoclipConn); charNoclipConn = nil
        disconnect(charNoclipAddedConn); charNoclipAddedConn = nil
        charNoclipCharacter = nil
        for part, original in pairs(charNoclipStates) do
            if part and part.Parent then pcall(function() part.CanCollide = original end) end
        end
        table.clear(charNoclipStates)
    end

    local function startCharacterNoclip()
        stopCharacterNoclip()
        if not S.NoclipEnabled then return end
        local function watchPart(part)
            if not part:IsA("BasePart") then return end
            if charNoclipStates[part] == nil then charNoclipStates[part] = part.CanCollide end
            if part.CanCollide then part.CanCollide = false end
        end
        local function watchCharacter(character)
            if charNoclipCharacter == character then return end
            disconnect(charNoclipAddedConn); charNoclipAddedConn = nil
            for part, original in pairs(charNoclipStates) do
                if part and part.Parent then pcall(function() part.CanCollide = original end) end
            end
            table.clear(charNoclipStates)
            charNoclipCharacter = character
            if not character then return end
            for _, part in ipairs(character:GetDescendants()) do watchPart(part) end
            charNoclipAddedConn = character.DescendantAdded:Connect(watchPart)
        end
        watchCharacter(LP.Character)
        charNoclipConn = RS.Stepped:Connect(function()
            if not S.NoclipEnabled then return end
            if LP.Character ~= charNoclipCharacter then watchCharacter(LP.Character) end
            -- Iterate cached parts, not the entire avatar hierarchy every frame.
            for part in pairs(charNoclipStates) do
                if part.Parent and part:IsDescendantOf(charNoclipCharacter) and part.CanCollide then
                    part.CanCollide = false
                end
            end
        end)
    end

    local function clearRagdollObject(child)
        if not child or not ragTags[child.Name] then return end
        pcall(function()
            if child:IsA("BoolValue") then
                child.Value = false
            elseif child:IsA("StringValue") or child:IsA("ObjectValue") then
                child:Destroy()
            end
        end)
    end

    local function bindNoRagdoll()
        disconnect(ragdollConn)
        ragdollConn = nil
        if not S.NoRagdollEnabled then return end
        local c = localCharacterModel()
        if not c then return end
        for _, child in ipairs(c:GetChildren()) do clearRagdollObject(child) end
        ragdollConn = c.ChildAdded:Connect(function(child)
            if S.NoRagdollEnabled then clearRagdollObject(child) end
        end)
    end

    local function ensureNoFall()
        if not S.NoFallEnabled then return end
        local c = localCharacterModel()
        if not c then return end
        local rec = fallRecords[c]
        if rec and (not rec.marker or not rec.marker.Parent) then
            fallRecords[c] = nil
            rec = nil
        end
        if not rec then
            local marker = c:FindFirstChild("NoFallDamage")
            if marker and marker:IsA("BoolValue") then
                rec = {marker = marker, created = false, original = marker.Value}
            elseif not marker then
                marker = Instance.new("BoolValue")
                marker.Name = "NoFallDamage"
                marker.Value = true
                marker.Parent = c
                rec = {marker = marker, created = true, original = nil}
            else
                return
            end
            fallRecords[c] = rec
        end
        if rec.marker and rec.marker.Parent and rec.marker:IsA("BoolValue") then
            rec.marker.Value = true
        end
    end

    local function restoreNoFall()
        for _, rec in pairs(fallRecords) do
            local marker = rec.marker
            if marker and marker.Parent then
                pcall(function()
                    if rec.created then marker:Destroy()
                    elseif marker:IsA("BoolValue") then marker.Value = rec.original end
                end)
            end
        end
        table.clear(fallRecords)
    end

    local function unbindStamina()
        disconnect(staminaConn)
        staminaConn = nil
        staminaValue = nil
        staminaLast = nil
        staminaWriting = false
    end

    local function bindStamina()
        unbindStamina()
        if not S.NoStaminaEnabled then return end
        local data = LP:FindFirstChild("Data")
        local st = data and data:FindFirstChild("Stamina")
        if not st or not st:IsA("ValueBase") then return end
        staminaValue = st
        staminaLast = st.Value
        staminaConn = st:GetPropertyChangedSignal("Value"):Connect(function()
            if not S.NoStaminaEnabled or staminaWriting or staminaValue ~= st then return end
            local value = st.Value
            if value < staminaLast then
                staminaWriting = true
                pcall(function() st.Value = staminaLast end)
                staminaWriting = false
            else
                staminaLast = value
            end
        end)
    end

    local function unbindDash(restore)
        disconnect(dashConn)
        disconnect(dashWaitConn)
        dashConn, dashWaitConn = nil, nil
        if restore and dashValue and dashValue.Parent and dashOriginal ~= nil then
            pcall(function() dashValue.Value = dashOriginal end)
        end
        dashValue, dashOriginal = nil, nil
    end

    local function bindDash()
        unbindDash(false)
        if not S.NoDashCDEnabled then return end
        local data = LP:FindFirstChild("Data")
        if not data then return end
        local haste = data:FindFirstChild("HasteStacks")
        if not haste or not haste:IsA("ValueBase") then
            dashWaitConn = data.ChildAdded:Connect(function(child)
                if S.NoDashCDEnabled and child.Name == "HasteStacks" then
                    task.defer(bindDash)
                end
            end)
            return
        end
        dashValue = haste
        dashOriginal = haste.Value
        pcall(function() haste.Value = 99 end)
        dashConn = haste:GetPropertyChangedSignal("Value"):Connect(function()
            if S.NoDashCDEnabled and dashValue == haste and haste.Value ~= 99 then
                pcall(function() haste.Value = 99 end)
            end
        end)
    end

    local function clearKnownCooldowns(c)
        if not c then return end
        local gunCD = c:FindFirstChild("GunFireCD")
        if gunCD then pcall(function() gunCD:Destroy() end) end
        for _, attr in ipairs({"IsSwinging", "CurrentM1"}) do
            if c:GetAttribute(attr) ~= nil then
                pcall(function() c:SetAttribute(attr, nil) end)
            end
        end
    end

    local function unbindCooldowns()
        disconnect(cooldownChildConn)
        cooldownChildConn = nil
        for _, conn in ipairs(cooldownAttrConns) do disconnect(conn) end
        table.clear(cooldownAttrConns)
    end

    local function bindCooldowns()
        unbindCooldowns()
        globalNoCooldowns = S.NoCooldownsEnabled
        if not S.NoCooldownsEnabled then return end
        local c = localCharacterModel()
        if not c then return end
        clearKnownCooldowns(c)
        cooldownChildConn = c.ChildAdded:Connect(function(child)
            if S.NoCooldownsEnabled and child.Name == "GunFireCD" then
                task.defer(function()
                    if S.NoCooldownsEnabled and child.Parent then pcall(function() child:Destroy() end) end
                end)
            end
        end)
        for _, attr in ipairs({"IsSwinging", "CurrentM1"}) do
            table.insert(cooldownAttrConns, c:GetAttributeChangedSignal(attr):Connect(function()
                if S.NoCooldownsEnabled and c:GetAttribute(attr) ~= nil then
                    pcall(function() c:SetAttribute(attr, nil) end)
                end
            end))
        end
    end

    CharTab:CreateSection("Movement")
    local FlyToggle = CharTab:CreateToggle({ Name = "Fly", CurrentValue=false, Flag="CharacterFly",
        Callback = function(state)
            S.FlyEnabled = state
            if state then startCharacterFly() else stopCharacterFly() end
        end })
    CharTab:CreateKeybind({ Name = "Fly Key", CurrentKeybind = "F", HoldToInteract = false, Flag = "CharacterFlyKey",
        Callback = function() FlyToggle:Set(not S.FlyEnabled) end })
    CharTab:CreateSlider({ Name = "Fly Speed", Range={20,250}, Increment=5,
        CurrentValue=70, Flag="CharacterFlySpeed", Callback = function(v) S.FlySpeed = v end })

    local NoclipToggle = CharTab:CreateToggle({ Name = "Noclip", CurrentValue=false, Flag="CharacterNoclip",
        Callback = function(state)
            S.NoclipEnabled = state
            if state then startCharacterNoclip() else stopCharacterNoclip() end
        end })
    CharTab:CreateKeybind({ Name = "Noclip Key", CurrentKeybind = "N", HoldToInteract = false, Flag = "CharacterNoclipKey",
        Callback = function() NoclipToggle:Set(not S.NoclipEnabled) end })
    CharTab:CreateLabel("Fly: WASD + Space/LeftShift | Noclip restores original collision states")

    local TPWalkToggle = CharTab:CreateToggle({ Name = "TP Walk", CurrentValue=false, Flag="TPWalk",
        Callback = function(state) CharacterValues.tpwalk = state end })
    CharTab:CreateKeybind({ Name = "TP Walk Key", CurrentKeybind = "G", HoldToInteract = false, Flag = "TPWalkKey",
        Callback = function() TPWalkToggle:Set(not CharacterValues.tpwalk) end })
    CharTab:CreateSlider({ Name = "TP Walk Speed", Range={1,15}, Increment=1,
        CurrentValue=1, Flag="TPWalkSpeed", Callback = function(v) CharacterValues.tpwalknum = v end })

    local InfJumpToggle = CharTab:CreateToggle({ Name = "Infinite Jump", CurrentValue=false, Flag="InfJump",
        Callback = function(state) CharacterValues.infjump = state end })
    CharTab:CreateKeybind({ Name = "Infinite Jump Key", CurrentKeybind = "I", HoldToInteract = false, Flag = "InfJumpKey",
        Callback = function() InfJumpToggle:Set(not CharacterValues.infjump) end })

    CharTab:CreateToggle({ Name = "Warp Dash (Long Dash)", CurrentValue=false, Flag="WarpDash",
        Callback = function(state) S.WarpDashEnabled = state end })
    CharTab:CreateLabel("Warp Dash is kept as an experimental long-dash helper.")
    CharTab:CreateToggle({ Name = "Haste Stacks", CurrentValue=false, Flag="Haste",
        Callback = function(state) S.HasteEnabled = state end })

    CharTab:CreateSection("Defense")
    CharTab:CreateToggle({ Name = "No Ragdoll", CurrentValue=false, Flag="NoRagdoll",
        Callback = function(state)
            S.NoRagdollEnabled = state
            bindNoRagdoll()
        end })
    CharTab:CreateToggle({ Name = "No Fall Damage", CurrentValue=false, Flag="NoFall",
        Callback = function(state)
            S.NoFallEnabled = state
            if state then ensureNoFall() else restoreNoFall() end
        end })
    CharTab:CreateToggle({ Name = "No Stamina Drain", CurrentValue=false, Flag="NoStamina",
        Callback = function(state)
            S.NoStaminaEnabled = state
            if state then bindStamina() else unbindStamina() end
        end })
    CharTab:CreateToggle({ Name = "No Dash Cooldown", CurrentValue=false, Flag="NoDashCD",
        Callback = function(state)
            S.NoDashCDEnabled = state
            if state then bindDash() else unbindDash(true) end
        end })
    CharTab:CreateToggle({ Name = "No Cooldowns", CurrentValue=false, Flag="NoCooldowns",
        Callback = function(state)
            S.NoCooldownsEnabled = state
            globalNoCooldowns = state
            if state then bindCooldowns() else unbindCooldowns() end
        end })

    CharTab:CreateSection("Misc")
    CharTab:CreateToggle({ Name = "Permanent EXP Bar", CurrentValue=false, Flag="PermExp",
        Callback = function(state)
            QolValues.permexp = state
            if not state then
                pcall(function()
                    LP.PlayerGui.Stats.UI.GradeSlider.Visible = false
                end)
            end
        end })

    task.spawn(function()
        while true do
            local delta = RS.Heartbeat:Wait()
            if CharacterValues.tpwalk then
                if LP.Character and LP.Character:FindFirstChild("Humanoid")
                    and LP.Character.Humanoid.MoveDirection.Magnitude > 0 then
                    LP.Character:TranslateBy(LP.Character.Humanoid.MoveDirection * CharacterValues.tpwalknum * delta * 10)
                end
            end
        end
    end)

    UIS.JumpRequest:Connect(function()
        if CharacterValues.infjump then
            local hum = LP.Character and LP.Character:FindFirstChildWhichIsA("Humanoid")
            if hum then hum:ChangeState(Enum.HumanoidStateType.Jumping) end
        end
    end)

    -- Legacy stack helpers are throttled; the defense toggles above are event-driven.
    task.spawn(function()
        while true do
            local active = S.NoFallEnabled or S.HasteEnabled or S.WarpDashEnabled
            task.wait(active and 0.1 or 0.5)
            if S.NoFallEnabled then ensureNoFall() end
            if S.HasteEnabled then
                local d = LP:FindFirstChild("Data")
                local b = d and d:FindFirstChild("HasteStacks")
                if b and b:IsA("ValueBase") and b.Value ~= 99 then b.Value = 99 end
            end
            if S.WarpDashEnabled then
                local d = LP:FindFirstChild("Data")
                local b = d and d:FindFirstChild("WarpDashStacks")
                if b and b:IsA("ValueBase") and b.Value ~= 1 then b.Value = 1 end
            end
        end
    end)

    -- One respawn listener owns all character-feature rebinding.
    LP.CharacterAdded:Connect(function()
        task.wait(0.3)
        if S.FlyEnabled then startCharacterFly() end
        if S.NoclipEnabled then startCharacterNoclip() end
        if S.NoRagdollEnabled then bindNoRagdoll() end
        if S.NoFallEnabled then ensureNoFall() end
        if S.NoStaminaEnabled then bindStamina() end
        if S.NoDashCDEnabled then bindDash() end
        if S.NoCooldownsEnabled then bindCooldowns() end
    end)
end

-- ============================================================
-- LOCK-ON TAB
-- ============================================================
local LockonTab = CombatTab -- merged into Combat

do
    local lkTarget, lkPart = nil, nil
    local lkLocked = false
    local lkCircle = Drawing.new("Circle")
    lkCircle.Visible = false; lkCircle.Radius = S.LockonFOV
    lkCircle.Color = Color3.new(1,1,1); lkCircle.Thickness = 1
    lkCircle.Filled = false; lkCircle.NumSides = 64

    local function validLk(obj)
        if not obj or not obj:IsA("Model") or isSelf(obj) then return false end
        local h = obj:FindFirstChild("Humanoid")
        if not h or h.Health <= 0 then return false end
        local ip = isPlr(obj)
        if S.LockonFilter == "NPCs Only" and ip then return false end
        if S.LockonFilter == "Players Only" and not ip then return false end
        return true
    end

    local function lkGetPart(obj)
        if not obj then return nil end
        if S.LockonPart == "Head" then return obj:FindFirstChild("Head") or root(obj) end
        if S.LockonPart == "Torso" then return obj:FindFirstChild("Torso") or obj:FindFirstChild("UpperTorso") or root(obj) end
        return root(obj)
    end

    local function lkFindTarget()
        local al = alive(); if not al then return nil end
        local isCam = S.LockonMode == "Camera"
        local isDist = S.LockonMode == "Distance"
        local mouse = not isCam and not isDist and UIS:GetMouseLocation()
        local center = isCam and Vector2.new(Camera.ViewportSize.X/2, Camera.ViewportSize.Y/2)
        local myRoot = isDist and root(LP.Character)
        local best, bestD = nil, isDist and math.huge or S.LockonFOV
        for _, obj in ipairs(al:GetChildren()) do
            if not validLk(obj) then continue end
            local part = lkGetPart(obj); if not part then continue end
            if isDist then
                if not myRoot then continue end
                local d = (myRoot.Position - part.Position).Magnitude
                if d < bestD then bestD = d; best = obj end
            else
                local sp, on = Camera:WorldToViewportPoint(part.Position)
                if not on then continue end
                local ref = isCam and center or mouse
                local d = (Vector2.new(sp.X, sp.Y) - ref).Magnitude
                if d <= S.LockonFOV and d < bestD then bestD = d; best = obj end
            end
        end
        return best
    end

    local function toggleLk()
        if lkLocked then
            lkLocked = false; lkTarget = nil; lkPart = nil
        else
            lkTarget = lkFindTarget()
            if lkTarget then lkPart = lkGetPart(lkTarget); lkLocked = true end
        end
    end

    RS.RenderStepped:Connect(function()
        local show = S.LockonShowFOV and S.LockonEnabled
        lkCircle.Visible = show
        if show then
            lkCircle.Radius = S.LockonFOV
            lkCircle.Color = lkLocked and Color3.new(1,0,0) or Color3.new(1,1,1)
            lkCircle.Position = S.LockonMode == "Cursor"
                and UIS:GetMouseLocation()
                or Vector2.new(Camera.ViewportSize.X/2, Camera.ViewportSize.Y/2)
        end
        if S.LockonEnabled then
            if S.LockonAuto and not lkLocked then
                local t = lkFindTarget()
                if t then lkTarget = t; lkPart = lkGetPart(t); lkLocked = true end
            end
            if lkLocked and lkTarget and lkPart and lkPart.Parent then
                if not validLk(lkTarget) then
                    lkLocked = false; lkTarget = nil; lkPart = nil
                else
                    lkPart = lkGetPart(lkTarget)
                    if lkPart then
                        local tp = lkPart.Position; local cp = Camera.CFrame.Position
                        if S.LockonStrength >= 100 then
                            local tcf = CFrame.lookAt(cp, tp)
                            Camera.CFrame = S.LockonSmooth and Camera.CFrame:Lerp(tcf, S.LockonSmoothness) or tcf
                        elseif S.LockonStrength > 0 then
                            local ml = Camera.CFrame.LookVector:Lerp((tp - cp).Unit, S.LockonStrength/100)
                            Camera.CFrame = CFrame.lookAt(cp, cp + ml)
                        end
                    else lkLocked = false; lkTarget = nil end
                end
            elseif lkLocked then lkLocked = false; lkTarget = nil; lkPart = nil end
        end
    end)

    LockonTab:CreateSection("Lock-On Settings")
    LockonTab:CreateToggle({ Name = "Lock-On", CurrentValue=false, Flag="Lockon",
        Callback = function(state)
            S.LockonEnabled = state
            if not state then lkLocked = false; lkTarget = nil end
        end })
    LockonTab:CreateKeybind({ Name = "Toggle Lock-On Key", CurrentKeybind = "Q",
        HoldToInteract = false, Flag = "LockonKey",
        Callback = function() if S.LockonEnabled then toggleLk() end end })
    LockonTab:CreateSlider({ Name = "Lock-On FOV", Range={10,200}, Increment=5,
        CurrentValue=45, Flag="LockonFOV", Callback = function(v) S.LockonFOV = v end })
    LockonTab:CreateDropdown({ Name = "Lock-On Mode", Options={"Cursor","Camera","Distance"},
        CurrentOption={"Cursor"}, MultipleOptions=false, Flag="LockonMode",
        Callback = function(v) S.LockonMode = type(v)=="table" and v[1] or v end })
    LockonTab:CreateDropdown({ Name = "Target Filter", Options={"All","NPCs Only","Players Only"},
        CurrentOption={"All"}, MultipleOptions=false, Flag="LockonFilter",
        Callback = function(v) S.LockonFilter = type(v)=="table" and v[1] or v end })
    LockonTab:CreateSlider({ Name = "Strength", Range={0,100}, Increment=5,
        CurrentValue=80, Flag="LockonStrength", Callback = function(v) S.LockonStrength = v end })
    LockonTab:CreateToggle({ Name = "Smooth Camera", CurrentValue=true, Flag="LockonSmooth",
        Callback = function(state) S.LockonSmooth = state end })
    LockonTab:CreateToggle({ Name = "Auto Lock", CurrentValue=false, Flag="LockonAuto",
        Callback = function(state) S.LockonAuto = state end })
    LockonTab:CreateToggle({ Name = "Show FOV Circle", CurrentValue=true, Flag="LockonFOVCircle",
        Callback = function(state) S.LockonShowFOV = state end })
end

-- ============================================================
-- AUTOFARMS TAB
-- ============================================================
local QuestTab = Window:CreateTab("Jobs", 10726204364)
QuestTab:CreateLabel("Quest, delivery, cooking and grade automation")

do
    -- AUTO COOK
    QuestTab:CreateSection("Auto Cook")
    local pot = Workspace.NPCS and Workspace.NPCS:FindFirstChild("Cooking Pot")
    local autoCook = false
    local cookBusy = false

    local Recipes = {
        CookedMeat    = {Name="Cooked Meat",    Ingredients={"Raw Meat"},                               Plating=nil},
        JelloSkewer   = {Name="Jello Skewer",   Ingredients={"Jello"},                                  Plating="Skewer"},
        MeatSkewer    = {Name="Meat Skewer",    Ingredients={"Cooked Meat","Spices"},                   Plating="Skewer"},
        SpicySoup     = {Name="Spicy Soup",     Ingredients={"Spices"},                                 Plating="Plate"},
        Bread         = {Name="Bread",          Ingredients={"Flour","Flour"},                          Plating=nil},
        GoldenBisque  = {Name="Golden Bisque",  Ingredients={"Cooked Meat","Spices","Uncharged Golden Bough"}, Plating="Plate"},
        Burger        = {Name="Burger",         Ingredients={"Cooked Meat","Spices","Bread","Bread"},   Plating=nil},
        CoffeeJelly   = {Name="Coffee Jelly",   Ingredients={"Cup of Coffee","Jello"},                  Plating=nil},
        ShiranoSpecial= {Name="Shirano Special",Ingredients={"Spicy Soup","Cooked Meat"},               Plating=nil},
    }
    local RecipeNames = {}
    for k, r in pairs(Recipes) do RecipeNames[#RecipeNames+1] = r.Name end
    table.sort(RecipeNames)
    local SelectedRecipe = Recipes.SpicySoup

    local function hasIngredients(recipe)
        local count = {}
        for _, item in ipairs(LP.Backpack:GetChildren()) do
            count[item.Name] = (count[item.Name] or 0) + 1
        end
        for _, ing in ipairs(recipe.Ingredients) do
            local c = count[ing] or 0
            if c < 1 then return false end
            count[ing] = c - 1
        end
        if recipe.Plating and (count[recipe.Plating] or 0) < 1 then return false end
        return true
    end

    local function equipTool(toolName)
        local tool = LP.Backpack:FindFirstChild(toolName)
        if tool then tool.Parent = LP.Character; task.wait(0.3); return true end
        return false
    end

    local function firePromptPot()
        if not pot then return end
        for _, p in ipairs(pot:GetDescendants()) do
            if p:IsA("ProximityPrompt") then fireproximityprompt(p); return end
        end
    end

    local function potHasIngredient(name)
        local added = pot and pot:FindFirstChild("AddedIngredients")
        return added and added:FindFirstChild(name) ~= nil
    end

    local function potHasPlating()
        local plating = pot and pot:FindFirstChild("PlatingAdded")
        return plating and plating.Value ~= ""
    end

    local function waitForPotIngredient(name, timeout)
        for _ = 1, (timeout or 5) * 5 do
            if potHasIngredient(name) then return true end
            task.wait(0.2)
        end
        return false
    end

    local function cookOne()
        if not hasIngredients(SelectedRecipe) then return false end
        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        if hrp and pot then hrp.CFrame = pot:GetPivot() * CFrame.new(0, 0, 5); task.wait(0.3) end
        firePromptPot(); task.wait(1)
        local scroll = LP.PlayerGui.Dialogue.MainFrame.Options.Scroll
        local startBtn = scroll:FindFirstChild("Option")
        if startBtn then clickButton(startBtn:FindFirstChild("OptionButton")) end
        task.wait(3)
        firePromptPot(); task.wait(1)
        for _, ing in ipairs(SelectedRecipe.Ingredients) do
            equipTool(ing)
            scroll = LP.PlayerGui.Dialogue.MainFrame.Options.Scroll
            local addBtn = scroll:FindFirstChild("Option")
            if addBtn then clickButton(addBtn:FindFirstChild("OptionButton")) end
            if not waitForPotIngredient(ing, 5) then return false end
            task.wait(0.3)
        end
        if SelectedRecipe.Plating then
            equipTool(SelectedRecipe.Plating)
            scroll = LP.PlayerGui.Dialogue.MainFrame.Options.Scroll
            local plateBtn = scroll:GetChildren()[3]
            if plateBtn then
                clickButton(plateBtn:FindFirstChild("OptionButton"))
                for _ = 1, 25 do if potHasPlating() then break end; task.wait(0.2) end
            end
            task.wait(0.3)
        end
        scroll = LP.PlayerGui.Dialogue.MainFrame.Options.Scroll
        scroll.CanvasPosition = Vector2.new(0, 100); task.wait(0.3)
        local completeBtn = scroll:GetChildren()[4]
        if completeBtn then clickButton(completeBtn:FindFirstChild("OptionButton")) end
        return true
    end

    local function autoCookLoop()
        while autoCook and not cookBusy do
            cookBusy = true
            if not hasIngredients(SelectedRecipe) then
                autoCook = false; cookBusy = false; break
            end
            if not cookOne() then autoCook = false end
            cookBusy = false
            task.wait(1)
        end
    end

    QuestTab:CreateDropdown({
        Name = "Recipe", Options = RecipeNames, CurrentOption = {"Spicy Soup"},
        MultipleOptions = false, Flag = "CookRecipe",
        Callback = function(selected)
            local sel = type(selected) == "table" and selected[1] or selected
            for _, r in pairs(Recipes) do if r.Name == sel then SelectedRecipe = r; break end end
        end,
    })

    QuestTab:CreateToggle({
        Name = "Auto Cook", CurrentValue = false, Flag = "AutoCook",
        Callback = function(state)
            autoCook = state
            if state then task.spawn(autoCookLoop) end
        end,
    })

    -- DOCKS DELIVERY
    QuestTab:CreateSection("Docks Delivery")
    local docksEnabled = false
    local docksBusy = false

    local function dockHasShipment()
        local al = Workspace:FindFirstChild("Alive")
        if not al then return false end
        local pc = al:FindFirstChild(LP.Name)
        return pc and pc:FindFirstChild("WhaleShipment") ~= nil
    end

    local function dockFindPirates()
        local pirates = {}
        local f = Workspace:FindFirstChild("NPCS")
        if f then
            for _, npc in ipairs(f:GetChildren()) do
                if npc.Name == "Twinhook Pirate" then table.insert(pirates, npc) end
            end
        end
        return pirates
    end

    local function dockGetQuest()
        local btn = scrollAndFind("Show me the available jobs", false)
        if not btn then btn = scrollAndFind("available jobs", false) end
        if not btn then btn = findButtonByText("Jobs", false) end
        if not btn then
            local ok, scroll = pcall(function() return LP.PlayerGui.Dialogue.MainFrame.Options.Scroll end)
            if ok and scroll then
                local first = scroll:FindFirstChild("Option")
                if first then btn = first:FindFirstChild("OptionButton") end
            end
        end
        if not btn then return false end
        safeClick(btn); task.wait(0.5)
        if not waitForDialogue(3) then return false end
        task.wait(0.3)
        local questBtn = scrollAndFind("Docks Delivery", false)
        if not questBtn then return false end
        safeClick(questBtn); task.wait(0.5)
        waitForClose(2)
        return hasQuest()
    end

    local function dockGetShipment()
        local pirates = dockFindPirates()
        if #pirates == 0 then return false end
        for _, pirate in ipairs(pirates) do
            if dockHasShipment() then return true end
            local pRoot = root(pirate)
            if pRoot then safeTP(pRoot.CFrame * CFrame.new(0,0,3)); task.wait(0.3) end
            interactWith(pirate); task.wait(0.5)
            if dockHasShipment() then return true end
        end
        return false
    end

    local function dockTurnIn()
        for _ = 1, 20 do
            if not hasQuest() or not docksEnabled then break end
            local contractor = getNearestNPC(DOCK_NPCS)
            if not contractor then task.wait(1); continue end
            local cRoot = root(contractor)
            if cRoot then safeTP(cRoot.CFrame * CFrame.new(0,0,3)); task.wait(0.4) end
            interactWith(contractor)
            if not waitForDialogue(3) then task.wait(1); continue end
            task.wait(0.5)
            pressV()
            local turnInBtn = scrollAndFind("I'm here to turn this in", false)
                or scrollAndFind("turn this in", false)
                or scrollAndFind("Turn In", false)
                or scrollAndFind("Complete", false)
            if not turnInBtn then
                local ok, scroll = pcall(function() return LP.PlayerGui.Dialogue.MainFrame.Options.Scroll end)
                if ok and scroll then
                    local btn3 = scroll:GetChildren()[3]
                    if btn3 then turnInBtn = btn3:FindFirstChild("OptionButton") end
                end
            end
            if not turnInBtn then task.wait(1); continue end
            safeClick(turnInBtn); task.wait(0.5)
            waitForClose(2)
            if not hasQuest() then return true end
            task.wait(0.5)
        end
        return not hasQuest()
    end

    local function docksLoop()
        while docksEnabled do
            if docksBusy then task.wait(0.2); continue end
            docksBusy = true
            local contractor = getNearestNPC(DOCK_NPCS)
            if not contractor then docksBusy = false; task.wait(2); continue end
            local cRoot = root(contractor)
            if cRoot then safeTP(cRoot.CFrame * CFrame.new(0,0,3)); task.wait(0.3) end
            interactWith(contractor); task.wait(0.5)
            if not waitForDialogue(3) then docksBusy = false; task.wait(2); continue end
            if not dockGetQuest() then docksBusy = false; task.wait(2); continue end
            if not dockGetShipment() then docksBusy = false; task.wait(2); continue end
            if cRoot then safeTP(cRoot.CFrame * CFrame.new(0,0,3)); task.wait(0.3) end
            if dockTurnIn() then
                for _ = 180, 1, -1 do if not docksEnabled then break end; task.wait(1) end
            else task.wait(2) end
            GuiService.SelectedObject = nil
            GuiService.GuiNavigationEnabled = false
            GuiService.AutoSelectGuiEnabled = false
            docksBusy = false
            task.wait(1)
        end
        GuiService.SelectedObject = nil
        GuiService.GuiNavigationEnabled = false
        GuiService.AutoSelectGuiEnabled = false
    end

    QuestTab:CreateToggle({
        Name = "Docks Delivery", CurrentValue = false, Flag = "DocksDelivery",
        Callback = function(state)
            docksEnabled = state
            if state then task.spawn(docksLoop) end
        end,
    })

    -- DEBT COLLECTOR
    QuestTab:CreateSection("Debt Collector")
    QuestTab:CreateLabel("Grade 8+ required")
    local debtEnabled = false
    local debtBusy = false
    local debtAttacking = false
    local debtAttackCon = nil

    local function getDebtTarget()
        local debtFolder = Workspace.NPCS:FindFirstChild("ContractNPCS")
        if not debtFolder then return nil end
        local dc = debtFolder:FindFirstChild("DebtCollector")
        if not dc then return nil end
        for _, child in ipairs(dc:GetChildren()) do
            if child:IsA("Model") then
                local jobID = child:GetAttribute("JobID")
                if jobID and type(jobID) == "number" then return child end
            end
        end
        return nil
    end

    local function stopDebtAttack()
        if debtAttackCon then debtAttackCon:Disconnect(); debtAttackCon = nil end
        debtAttacking = false
    end

    local function startDebtAttack(target)
        if debtAttacking then return end
        debtAttacking = true
        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
        local tHrp = target:FindFirstChild("HumanoidRootPart") or target:FindFirstChild("Torso")
        if hrp and tHrp then hrp.CFrame = tHrp.CFrame end
        debtAttackCon = RS.RenderStepped:Connect(function()
            if not debtAttacking or not target or not target.Parent then return end
            local hum = target:FindFirstChild("Humanoid")
            if not hum or hum.Health <= 0 then stopDebtAttack(); return end
            local char = LP.Character; if not char then return end
            local weapon = char:FindFirstChild("Weapon")
            local humanoid = char:FindFirstChild("Humanoid")
            if weapon and humanoid then
                local wv = weapon.Value
                if wv and wv ~= "" then
                    local wi = RepStore:FindFirstChild("WeaponINFO")
                    if wi then
                        local wd = wi:FindFirstChild(wv)
                        if wd then
                            local anim = wd:FindFirstChild("AttackAnimation1")
                            local animator = humanoid:FindFirstChild("Animator")
                            if anim and animator then
                                local track = animator:LoadAnimation(anim)
                                track:Play(); track:AdjustSpeed(50)
                            end
                        end
                    end
                end
            end
        end)
    end

    local function debtTurnIn()
        local contractor = getNearestNPC(DOCK_NPCS)
        if not contractor then return false end
        local cRoot = root(contractor)
        if cRoot then safeTP(cRoot.CFrame * CFrame.new(0,0,3)); task.wait(0.3) end
        interactWith(contractor)
        if not waitForDialogue(3) then return false end
        task.wait(0.3)
        local turnInBtn = scrollAndFind("Turn In", false) or scrollAndFind("Complete", false)
        if not turnInBtn then
            local ok, scroll = pcall(function() return LP.PlayerGui.Dialogue.MainFrame.Options.Scroll end)
            if ok and scroll then
                local btn3 = scroll:GetChildren()[3]
                if btn3 then turnInBtn = btn3:FindFirstChild("OptionButton") end
            end
        end
        if not turnInBtn then return false end
        safeClick(turnInBtn); task.wait(0.5)
        waitForClose(2)
        return not hasQuest()
    end

    local function debtLoop()
        while debtEnabled do
            if debtBusy then task.wait(0.2); continue end
            debtBusy = true
            if not hasQuest() then
                local contractor = getNearestNPC(DOCK_NPCS)
                if not contractor then debtBusy = false; task.wait(1); continue end
                local cRoot = root(contractor)
                if cRoot then safeTP(cRoot.CFrame * CFrame.new(0,0,3)); task.wait(0.3) end
                interactWith(contractor); task.wait(0.5)
                if not waitForDialogue(3) then debtBusy = false; task.wait(1); continue end
                local btn = findButtonByText("Jobs", false)
                if not btn then
                    local ok, scroll = pcall(function() return LP.PlayerGui.Dialogue.MainFrame.Options.Scroll end)
                    if ok and scroll then
                        local first = scroll:FindFirstChild("Option")
                        if first then btn = first:FindFirstChild("OptionButton") end
                    end
                end
                if btn then safeClick(btn); task.wait(0.5) end
                if not waitForDialogue(3) then debtBusy = false; task.wait(1); continue end
                local questBtn = scrollAndFind("Debt Collector", false)
                if not questBtn then debtBusy = false; task.wait(1); continue end
                safeClick(questBtn); task.wait(0.5)
                waitForClose(2)
            end
            local target = getDebtTarget()
            if not target then debtBusy = false; task.wait(2); continue end
            local tRoot = root(target)
            if tRoot then safeTP(tRoot.CFrame * CFrame.new(0,0,3)); task.wait(0.5) end
            interactWith(target); task.wait(0.5)
            if waitForDialogue(2) then
                local attackBtn = scrollAndFind("Attack", false)
                if not attackBtn then
                    local ok, scroll = pcall(function() return LP.PlayerGui.Dialogue.MainFrame.Options.Scroll end)
                    if ok and scroll then
                        local btn3 = scroll:GetChildren()[3]
                        if btn3 then attackBtn = btn3:FindFirstChild("OptionButton") end
                    end
                end
                if attackBtn then safeClick(attackBtn); task.wait(0.5); waitForClose(2) end
            end
            startDebtAttack(target)
            for _ = 1, 30 do
                task.wait(1)
                local hum = target:FindFirstChild("Humanoid")
                if not hum or hum.Health <= 0 then break end
            end
            stopDebtAttack()
            if debtTurnIn() then
                for _ = 180, 1, -1 do if not debtEnabled then break end; task.wait(1) end
            else task.wait(2) end
            debtBusy = false; task.wait(1)
        end
        stopDebtAttack()
    end

    QuestTab:CreateToggle({
        Name = "Debt Collector", CurrentValue = false, Flag = "AutoDebt",
        Callback = function(state)
            debtEnabled = state
            if state then task.spawn(debtLoop) end
            if not state then stopDebtAttack() end
        end,
    })

